input.content:
//! Helpers that replicate Java/JDK formatting and parsing semantics.

/// Format an f64 exactly like `java.lang.Double.toString` (which Jackson uses
/// when writing JSON numbers).
///
/// Java rules: shortest decimal digits that uniquely identify the value;
/// plain notation when 10^-3 <= |v| < 10^7, otherwise scientific notation with
/// one digit before the decimal point and an "E" exponent.
pub fn java_double_to_string(v: f64) -> String {
    if v.is_nan() {
        return "NaN".to_string();
    }
    if v.is_infinite() {
        return if v > 0.0 { "Infinity".to_string() } else { "-Infinity".to_string() };
    }
    if v == 0.0 {
        return if v.is_sign_negative() { "-0.0".to_string() } else { "0.0".to_string() };
    }
    let neg = v < 0.0;
    let a = v.abs();
    // Shortest round-trip digits, via Rust's LowerExp (uses the same shortest
    // representation algorithm as Display).
    let sci = format!("{:e}", a); // e.g. "2.002637639e7", "5e-3", "1e20"
    let (mant, exp) = sci.split_once('e').unwrap();
    let exp: i32 = exp.parse().unwrap();
    // digits without decimal point
    let digits: String = mant.chars().filter(|c| *c != '.').collect();
    let digits = digits.trim_end_matches('0');
    let digits = if digits.is_empty() { "0" } else { digits };

    let mut out = String::new();
    if neg {
        out.push('-');
    }
    if exp >= -3 && exp < 7 {
        // plain notation.  value = 0.digits * 10^(exp+1)  => point after exp+1 digits
        let point = exp + 1; // number of integer digits (>=1 here since exp>=-3 could make point 0 or negative)
        if point <= 0 {
            out.push_str("0.");
            for _ in 0..(-point) {
                out.push('0');
            }
            out.push_str(digits);
        } else {
            let d = digits.chars().collect::<Vec<char>>();
            let n = point as usize;
            if d.len() <= n {
                out.extend(d.iter());
                for _ in d.len()..n {
                    out.push('0');
                }
                out.push_str(".0");
            } else {
                out.extend(d.iter().take(n));
                out.push('.');
                out.extend(d.iter().skip(n));
            }
        }
    } else {
        // scientific notation: d.dddEexp
        let d = digits.chars().collect::<Vec<char>>();
        out.push(d[0]);
        out.push('.');
        if d.len() == 1 {
