{"content": "//! Helpers that replicate Java/JDK formatting and parsing semantics.

/// Format an f64 exactly like `java.lang.Double.toString` (which Jackson uses
/// when writing JSON numbers).
///
/// Java rules: shortest decimal digits that uniquely identify the value;
/// plain notation when 10^-3 <= |v| < 10^7, otherwise scientific notation with
/// one digit before the decimal point and an "E" exponent.
pub fn java_double_to_string(v: f64) -> String {
    if v.is_nan() {
        return "NaN".to_string();
    }
    if v.is_infinite() {
        return if v > 0.0 { "Infinity".to_string() } else { "-Infinity".to_string() };
    }
    if v == 0.0 {
        return if v.is_sign_negative() { "-0.0".to_string() } else { "0.0".to_string() };
    }
    let neg = v < 0.0;
    let a = v.abs();
    // Shortest round-trip digits: Rust's LowerExp uses the same shortest
    // representation algorithm as Display, e.g. "2.002637639e7", "5e-3".
    let sci = format!("{:e}", a);
    let (mant, exp) = sci.split_once('e').unwrap();
    let exp: i32 = exp.parse().unwrap();
    let mut digits: String = mant.chars().filter(|c| *c != '.').collect();
    // strip trailing zeros (shortest form may still carry them, e.g. "1.0e20")
    while digits.len() > 1 && digits.ends_with('0') {
        digits.pop();
    }

    let mut out = String::new();
    if neg {
        out.push('-');
    }
    if exp >= -3 && exp < 7 {
        // plain notation: value = digits * 10^(exp - (digits.len()-1))
        // decimal point sits after (exp+1) digits
        let point = exp + 1;
        if point <= 0 {
            out.push_str("0.");
            for _ in 0..(-point) {
                out.push('0');
            }
            out.push_str(&digits);
        } else {
            let n = point as usize;
            if digits.len() <= n {
                out.push_str(&digits);
                for _ in digits.len()..n {
                    out.push('0');
                }
                out.push_str(".0");
            } else {
                out.push_str(&digits[..n]);
                out.push('.');
                out.push_str(&digits[n..]);
            }
        }
    } else {
        // scientific notation: d.dddEexp
        out.push_str(&digits[..1]);
        out.push('.');
        if digits.len() == 1 {
            out.push('0');
        } else {
            out.push_str(&digits[1..]);
        }
        out.push('E');
        out.push_str(&exp.to_string());
    }
    out
}

/// Escape a string the way Jackson does (minimal JSON escaping, raw UTF-8).
pub fn write_json_string(out: &mut String, s: &str) {
    out.push('"');
    for ch in s.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\u{08}' => out.push_str("\\b"),
            '\t' => out.push_str("\\t"),
            '\n' => out.push_str("\\n"),
            '\u{0c}' => out.push_str("\\f"),
            '\r' => out.push_str("\\r"),
            c if (c as u32) < 0x20 => {
                out.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => out.push(c),
        }
    }
    out.push('"');
}

/// Mimic `java.lang.Long.toString`/`Double.toString` for JSON scalars turned
/// into Strings by Jackson coercion.
pub fn java_number_to_string(v: &serde_json::Number) -> String {
    if let Some(u) = v.as_u64() {
        return u.to_string();
    }
    if let Some(i) = v.as_i64() {
        return i.to_string();
    }
    if let Some(f) = v.as_f64() {
        return java_double_to_string(f);
    }
    v.to_string()
}

/// Mimic `java.util.Locale.toString()` normalization applied by Jackson when a
/// Locale is deserialized from a String: split on '_', language lower-cased,
/// country upper-cased, variant as-is.
pub fn normalize_locale(s: &str) -> String {
    let parts: Vec<&str> = s.splitn(3, '_').collect();
    let mut out = String::new();
    if !parts.is_empty() {
        out.push_str(&parts[0].to_lowercase());
    }
    if parts.len() > 1 {
        out.push('_');
        out.push_str(&parts[1].to_uppercase());
    }
    if parts.len() > 2 {
        out.push('_');
        out.push_str(parts[2]);
    }
    out
}

/// Mimic commons-beanutils `ConvertUtils.convert(String, Boolean.class)` using
/// the standard BooleanConverter (defaults to false).
pub fn convert_utils_bool(s: &str) -> bool {
    let t = s.trim().to_lowercase();
    matches!(t.as_str(), "true" | "yes" | "y" | "t" | "on" | "1")
}

/// Mimic commons-beanutils `ConvertUtils.convert(String, Integer.class)`:
/// on parse failure the registered default (0) is returned.
pub fn convert_utils_i32(s: &str) -> i32 {
    let t = s.trim();
    match t.parse::<i32>() {
        Ok(v) => v,
        Err(_) => {
            if let Some(stripped) = t.strip_prefix('+') {
                stripped.trim().parse::<i32>().unwrap_or(0)
            } else {
                0
            }
        }
    }
}

/// Mimic commons-beanutils `ConvertUtils.convert(String, Double.class)`:
/// on parse failure the registered default (0.0) is returned.
pub fn convert_utils_f64(s: &str) -> f64 {
    let t = s.trim();
    if let Ok(v) = t.parse::<f64>() {
        return v;
    }
    // java.lang.Double.parseDouble accepts hexadecimal floating point "0x1p3"
    if let Some(v) = parse_java_hex_float(t) {
        return v;
    }
    if t.eq_ignore_ascii_case("nan") {
        return f64::NAN;
    }
    if t.eq_ignore_ascii_case("infinity") {
        return f64::INFINITY;
    }
    if t.eq_ignore_ascii_case("-infinity") {
        return f64::NEG_INFINITY;
    }
    0.0
}

fn parse_java_hex_float(t: &str) -> Option<f64> {
    let lower = t.to_lowercase();
    let (neg, rest) = match lower.strip_prefix('-') {
        Some(r) => (true, r),
        None => (false, lower.as_str()),
    };
    let s = rest.strip_prefix("0x")?;
    let (mant, exp) = match s.split_once('p') {
        Some((m, e)) => (m, e.parse::<i32>().ok()?),
        None => (s, 0),
    };
    let (int_part, frac_part) = match mant.split_once('.') {
        Some((i, f)) => (i, f),
        None => (mant, ""),
    };
    if int_part.is_empty() && frac_part.is_empty() {
        return None;
    }
    let mut value: f64 = 0.0;
    for c in int_part.chars() {
        value = value * 16.0 + c.to_digit(16)? as f64;
    }
    let mut scale = 1.0 / 16.0;
    for c in frac_part.chars() {
        value += c.to_digit(16)? as f64 * scale;
        scale /= 16.0;
    }
    let r = value * 2f64.powi(exp);
    Some(if neg { -r } else { r })
}

/// Mimic `org.apache.commons.lang3.math.NumberUtils.isParsable`.
pub fn number_utils_is_parsable(str: &str) -> bool {
    if str.is_empty() {
        return false;
    }
    let bytes = str.as_bytes();
    let last = bytes[bytes.len() - 1];
    if !last.is_ascii_digit() {
        return false;
    }
    if !bytes[0].is_ascii_digit() && bytes[0] != b'-' && bytes[0] != b'.' {
        return false;
    }
    if str.contains("0x") || str.contains("0X") {
        return false;
    }
    let body = if bytes[0] == b'-' { &str[1..] } else { str };
    if body.is_empty() {
        return false;
    }
    let mut dots = 0usize;
    let mut es = 0usize;
    let mut digits = 0usize;
    let chars: Vec<char> = body.chars().collect();
    for (i, c) in chars.iter().enumerate() {
        match c {
            '0'..='9' => digits += 1,
            '.' => {
                dots += 1;
                if dots > 1 {
                    return false;
                }
            }
            'e' | 'E' => {
                es += 1;
                if es > 1 {
                    return false;
                }
                let rest: String = chars[i + 1..].iter().collect();
                let rest = rest.strip_prefix('+').or_else(|| rest.strip_prefix('-')).unwrap_or(&rest);
                if rest.is_empty() || !rest.chars().all(|c| c.is_ascii_digit()) {
                    return false;
                }
            }
            '+' | '-' => {
                if i == 0 || (chars[i - 1] != 'e' && chars[i - 1] != 'E') {
                    return false;
                }
            }
            _ => return false,
        }
    }
    digits > 0
}

/// Mimic `org.apache.commons.lang3.math.NumberUtils.isDigits`.
pub fn number_utils_is_digits(str: &str) -> bool {
    !str.is_empty() && str.chars().all(|c| c.is_ascii_digit())
}

/// Mimic `java.lang.Object.toString()` for arbitrary Jackson-deserialized
/// values (used by PropertyValueConverter.convertToDatabaseColumn).
pub fn java_value_to_string(v: &serde_json::Value) -> String {
    match v {
        serde_json::Value::Null => "null".to_string(),
        serde_json::Value::Bool(b) => b.to_string(),
        serde_json::Value::Number(n) => java_number_to_string(n),
        serde_json::Value::String(s) => s.clone(),
        serde_json::Value::Array(arr) => {
            let mut out = String::from("[");
            for (i, item) in arr.iter().enumerate() {
                if i > 0 {
                    out.push_str(", ");
                }
                out.push_str(&java_value_to_string(item));
            }
            out.push(']');
            out
        }
        serde_json::Value::Object(map) => {
            let mut out = String::from("{");
            for (i, (k, val)) in map.iter().enumerate() {
                if i > 0 {
                    out.push_str(", ");
                }
                out.push_str(k);
                out.push('=');
                out.push_str(&java_value_to_string(val));
            }
            out.push('}');
            out
        }
    }
}

fn point2d_prefix() -> Vec<u8> {
    let hex = "aced00057372001c6a6176612e6177742e67656f6d2e506f696e74324424446f75626c65555bf8ca09a31d5f02000244000178440001797870";
    (0..hex.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap())
        .collect()
}

/// Serialize a point the way Java's ObjectOutputStream would
/// (`java.awt.geom.Point2D$Double`).
pub fn serialize_point2d_double(x: f64, y: f64) -> Vec<u8> {
    let mut out = point2d_prefix();
    out.extend_from_slice(&x.to_bits().to_be_bytes());
    out.extend_from_slice(&y.to_bits().to_be_bytes());
    out
}

/// Parse a Java-serialized `Point2D$Double` blob. Returns None if the blob is
/// not in exactly that format.
pub fn deserialize_point2d_double(data: &[u8]) -> Option<(f64, f64)> {
    let prefix = point2d_prefix();
    if data.len() != prefix.len() + 16 {
