/// The resource kinds served by the API.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ResourceType {
    Users,
    Groups,
    Roles,
    Layers,
    DataSources,
    Appearances,
}

impl ResourceType {
    pub fn from_path(p: &str) -> Option<ResourceType> {
        match p {
            "users" => Some(ResourceType::Users),
            "groups" => Some(ResourceType::Groups),
            "roles" => Some(ResourceType::Roles),
            "layers" => Some(ResourceType::Layers),
            "layerdatasources" => Some(ResourceType::DataSources),
            "layerappearances" => Some(ResourceType::Appearances),
            _ => None,
        }
    }
}

/// The set of private, non-static, primitive/wrapper/String fields for each
/// entity class (EntityUtil.getFilterableOrRestrictableFieldNames), used for
/// `output:only` and /filter. Order mirrors FieldUtils.getAllFieldsList
/// (subclass fields first).
pub fn filterable_fields(rt: ResourceType) -> Vec<&'static str> {
    match rt {
        ResourceType::Users => vec![
            "accountName", "password", "active", "firstName", "lastName", "email", "id",
        ],
        ResourceType::Groups => vec!["name", "id"],
        ResourceType::Roles => vec!["name", "description", "id"],
        ResourceType::Layers => vec!["name", "description", "id"],
        ResourceType::DataSources => vec!["name", "type", "url", "format", "id"],
        ResourceType::Appearances => vec![
            "attribution", "hoverable", "clickable", "hoverTemplate", "name", "maxResolution",
            "minResolution", "opacity", "visible", "id",
        ],
    }
}

/// Field -> java type for filter value casting.
#[derive(Clone, Copy, PartialEq)]
pub enum FieldType {
    Str,
    Int,
    BoolPrim,
    BoolWrap,
    Double,
}

pub fn field_type(rt: ResourceType, field: &str) -> Option<FieldType> {
    match rt {
        ResourceType::Users => match field {
            "id" => Some(FieldType::Int),
            "active" => Some(FieldType::BoolPrim),
            "accountName" | "password" | "firstName" | "lastName" | "email" => {
                Some(FieldType::Str)
            }
            _ => None,
        },
        ResourceType::Groups => match field {
            "id" => Some(FieldType::Int),
            "name" => Some(FieldType::Str),
            _ => None,
        },
        ResourceType::Roles | ResourceType::Layers => match field {
            "id" => Some(FieldType::Int),
            "name" | "description" => Some(FieldType::Str),
            _ => None,
        },
        ResourceType::DataSources => match field {
            "id" => Some(FieldType::Int),
            "name" | "type" | "url" | "format" => Some(FieldType::Str),
            _ => None,
        },
        ResourceType::Appearances => match field {
            "id" => Some(FieldType::Int),
            "attribution" | "hoverTemplate" | "name" => Some(FieldType::Str),
            "hoverable" | "clickable" | "visible" => Some(FieldType::BoolWrap),
            "maxResolution" | "minResolution" | "opacity" => Some(FieldType::Double),
            _ => None,
        },
    }
}

/// DB column for a filterable/restrictable field.
pub fn field_column(rt: ResourceType, field: &str) -> Option<&'static str> {
    match rt {
        ResourceType::Users => match field {
            "id" => Some("p.id"),
            "firstName" => Some("p.firstname"),
            "lastName" => Some("p.lastname"),
            "email" => Some("p.email"),
            "accountName" => Some("u.accountname"),
            "password" => Some("u.password"),
            "active" => Some("u.active"),
            _ => None,
        },
        ResourceType::Groups => match field {
            "id" => Some("usergroups.id"),
            "name" => Some("usergroups.name"),
            _ => None,
        },
        ResourceType::Roles => match field {
            "id" => Some("roles.id"),
            "name" => Some("roles.name"),
            "description" => Some("roles.description"),
            _ => None,
        },
        ResourceType::Layers => match field {
            "id" => Some("layers.id"),
            "name" => Some("layers.name"),
            "description" => Some("layers.description"),
            _ => None,
        },
        ResourceType::DataSources => match field {
            "id" => Some("d.id"),
            "name" => Some("d.name"),
            "type" => Some("d.type"),
            "url" => Some("d.url"),
            "format" => Some("d.format"),
            _ => None,
        },
        ResourceType::Appearances => match field {
            "id" => Some("layerappearances.id"),
            "attribution" => Some("layerappearances.attribution"),
            "hoverable" => Some("layerappearances.hoverable"),
            "clickable" => Some("layerappearances.clickable"),
            "hoverTemplate" => Some("layerappearances.hovertemplate"),
            "name" => Some("layerappearances.name"),
            "maxResolution" => Some("layerappearances.maxresolution"),
            "minResolution" => Some("layerappearances.minresolution"),
            "opacity" => Some("layerappearances.opacity"),
            "visible" => Some("layerappearances.visible"),
            _ => None,
        },
    }
}

// ---------------------------------------------------------------------------
// Row -> entity helpers
// ---------------------------------------------------------------------------

fn get_opt<T: tokio_postgres::types::FromSql + 'static>(row: &Row, col: &str) -> Option<T> {
    row.try_get(col)
}

pub fn point_from(x: Option<f64>, y: Option<f64>) -> Option<Point> {
    // Hibernate maps embedded Point2D columns individually; a point is "null"
    // when both columns are null. Java object semantics: if the embedded
    // columns are all null the entity reference is null.
    match (x, y) {
        (None, None) => None,
        (x, y) => Some(Point { x: x.unwrap_or(0.0), y: y.unwrap_or(0.0) }),
    }
}

pub fn role_from_row(row: &Row) -> Role {
    Role {
        id: row.get("id"),
        created: get_opt(row, "created"),
        modified: get_opt(row, "modified"),
        name: row.get("name"),
        description: get_opt(row, "description"),
        fresh: false,
    }
}

pub fn user_from_rows(p_row: &Row, u_row: Option<&Row>) -> User {
    // combined persons/users select
    User {
        id: p_row.get("id"),
        created: get_opt(p_row, "created"),
        modified: get_opt(p_row, "modified"),
        first_name: get_opt(p_row, "firstname"),
        last_name: get_opt(p_row, "lastname"),
        email: get_opt(p_row, "email"),
        birthday: get_opt(p_row, "birthday"),
        language: get_opt(p_row, "language"),
        account_name: u_row.map(|r| get_opt(r, "accountname")).flatten(),
        password: u_row.map(|r| get_opt(r, "password")).flatten(),
        active: u_row.map(|r| r.get::<_, Option<bool>>("active")).flatten().unwrap_or(false),
        roles: Vec::new(),
        user_group_ids: Vec::new(),
        fresh: false,
        restricted: None,
    }
}

pub fn user_from_joined_row(row: &Row) -> User {
    // single-row join persons p + users u with aliased columns
    User {
        id: row.get("u_id"),
        created: row.try_get("u_created").unwrap_or(None),
        modified: row.try_get("u_modified").unwrap_or(None),
        first_name: row.try_get("u_firstname").unwrap_or(None),
        last_name: row.try_get("u_lastname").unwrap_or(None),
        email: row.try_get("u_email").unwrap_or(None),
        birthday: row.try_get("u_birthday").unwrap_or(None),
        language: row.try_get("u_language").unwrap_or(None),
        account_name: row.try_get("u_accountname").unwrap_or(None),
        password: row.try_get("u_password").unwrap_or(None),
        active: row.try_get::<_, Option<bool>>("u_active").unwrap_or(None).unwrap_or(false),
        roles: Vec::new(),
        user_group_ids: Vec::new(),
        fresh: false,
        restricted: None,
    }
}

pub fn group_from_row(row: &Row) -> UserGroup {
    UserGroup {
        id: row.get("id"),
        created: get_opt(row, "created"),
        modified: get_opt(row, "modified"),
        name: get_opt(row, "name"),
