pub fn appearance_from_row(row: &Row) -> LayerAppearance {
    LayerAppearance {
        id: row.get("id"),
        created: get_opt(row, "created"),
        modified: get_opt(row, "modified"),
        attribution: get_opt(row, "attribution"),
        hoverable: get_opt(row, "hoverable"),
        clickable: get_opt(row, "clickable"),
        hover_template: get_opt(row, "hovertemplate"),
        properties: Vec::new(),
        properties_raw: None,
        name: get_opt(row, "name"),
        max_resolution: get_opt(row, "maxresolution"),
        min_resolution: get_opt(row, "minresolution"),
        opacity: get_opt(row, "opacity"),
        visible: get_opt(row, "visible"),
        fresh: false,
        restricted: None,
    }
