{"content": "//! Entity model mirroring the SHOGun-Core JPA entities of the slice, plus
//! database load/save logic that mirrors what Hibernate does.

use chrono::{NaiveDate, NaiveDateTime};
use serde_json::Value;
use std::collections::HashMap;
use tokio_postgres::Row;

use crate::javadoc;

#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub enum Permission {
    Admin,
    Create,
    Delete,
    Update,
    Read,
}

impl Permission {
    /// Mimics Permission.fromString (case-insensitive, null on unknown).
    pub fn from_string(s: &str) -> Option<Permission> {
        match s.to_uppercase().as_str() {
            "ADMIN" => Some(Permission::Admin),
            "CREATE" => Some(Permission::Create),
            "DELETE" => Some(Permission::Delete),
            "UPDATE" => Some(Permission::Update),
            "READ" => Some(Permission::Read),
            _ => None,
        }
    }
    pub fn as_str(&self) -> &'static str {
        match self {
            Permission::Admin => "ADMIN",
            Permission::Create => "CREATE",
            Permission::Delete => "DELETE",
            Permission::Update => "UPDATE",
            Permission::Read => "READ",
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum DsKind {
    Base,
    ImageWms,
    TileWms,
    Wfs,
    Wmts,
    Xyz,
}

#[derive(Clone, Copy, PartialEq, Debug)]
pub struct Point {
    pub x: f64,
    pub y: f64,
}

/// A value of `LayerAppearance.properties`.
#[derive(Clone, PartialEq, Debug)]
pub enum PropValue {
    Str(String),
    Long(i64),
    Double(f64),
    Bool(bool),
}

impl PropValue {
    /// Mimics PropertyValueConverter.convertToEntityAttribute.
    pub fn from_db_string(s: &str) -> PropValue {
        let lower = s.to_lowercase();
        if lower == "true" {
            return PropValue::Bool(true);
        }
        if lower == "false" {
            return PropValue::Bool(false);
        }
        if javadoc::number_utils_is_parsable(s) {
            if javadoc::number_utils_is_digits(s)
                || (s.starts_with('-') && javadoc::number_utils_is_digits(&s[1..]))
            {
                if let Ok(v) = s.parse::<i64>() {
                    return PropValue::Long(v);
                }
            }
            if let Ok(v) = s.parse::<f64>() {
                return PropValue::Double(v);
            }
        }
        PropValue::Str(s.to_string())
    }
}

