    Roles,
    Layers,
    DataSources,
    Appearances,
}

impl ResourceType {
    pub fn from_path(p: &str) -> Option<ResourceType> {
        match p {
            "users" => Some(ResourceType::Users),
            "groups" => Some(ResourceType::Groups),
            "roles" => Some(ResourceType::Roles),
