fn get_opt<T: tokio_postgres::types::FromSql + 'static>(row: &Row, col: &str) -> Option<T> {
    row.try_get(col)
}

pub fn point_from(x: Option<f64>, y: Option<f64>) -> Option<Point> {
    // Hibernate maps embedded Point2D columns individually; a point is "null"
    // when both columns are null. Java object semantics: if the embedded
    // columns are all null the entity reference is null.
    match (x, y) {
        (None, None) => None,
        (x, y) => Some(Point { x: x.unwrap_or(0.0), y: y.unwrap_or(0.0) }),
    }
}

