//! Database access: connection pool, entity loading (full / restricted /
//! filtered), id allocation from `hibernate_sequences` and all writes,
//! mirroring what Hibernate does in the original.

use chrono::{Local, NaiveDateTime};
use deadpool_postgres::{Config as DpConfig, Pool, Runtime};
use tokio_postgres::types::ToSql;
use tokio_postgres::{NoTls, Row};

use crate::model::*;

pub fn create_pool(database_url: &str) -> Result<Pool, String> {
    let mut pg_cfg = tokio_postgres::Config::from_str(database_url)
        .map_err(|e| format!("invalid DATABASE_URL: {}", e))?;
    // keep default application_name quiet
    let _ = &mut pg_cfg;
    let mut cfg = DpConfig::from(pg_cfg.clone());
    cfg.pool = Some(deadpool_postgres::PoolConfig::default());
    let manager = cfg.create_manager(Some(Runtime::Tokio1));
    let pool = Pool::builder(manager)
        .max_size(8)
        .build()
        .map_err(|e| format!("pool build error: {}", e))?;
    Ok(pool)
}

pub fn now() -> NaiveDateTime {
    Local::now().naive_local()
}

/// Allocate the next id the way Hibernate's TableGenerator does:
/// new id = next_val + 1, then next_val = new id. Executed with autocommit so
/// the value is consumed even if the surrounding business transaction rolls
/// back (matching the original).
pub async fn next_id(pool: &Pool) -> Result<i32, String> {
    let c = pool.get().await.map_err(|e| e.to_string())?;
    let row = c
        .query_one(
            "INSERT INTO hibernate_sequences (sequence_name, next_val) VALUES ('default', 1)
             ON CONFLICT (sequence_name)
             DO UPDATE SET next_val = COALESCE(hibernate_sequences.next_val, 0) + 1
             RETURNING next_val",
            &[],
        )
        .await
        .map_err(|e| e.to_string())?;
    let v: i64 = row.get("next_val");
    Ok(v as i32)
}

pub struct DynQuery {
    pub sql: String,
    pub params: Vec<Box<dyn ToSql + Sync>>,
}

impl DynQuery {
    pub fn refs(&self) -> Vec<&(dyn ToSql + Sync)> {
        self.params.iter().map(|b| b.as_ref() as &(dyn ToSql + Sync)).collect()
    }
}

// ---------------------------------------------------------------------------
// Users
// ---------------------------------------------------------------------------

const USER_COLS_FULL: &str = "p.id AS u_id, p.created AS u_created, p.modified AS u_modified, \
     p.birthday AS u_birthday, p.email AS u_email, p.firstname AS u_firstname, \
     p.language AS u_language, p.lastname AS u_lastname, \
     u.accountname AS u_accountname, u.active AS u_active, u.password AS u_password";

/// Load users (full entities incl. roles and group ids).
/// `ids`: restrict to these ids; `filter`: extra WHERE clause with $n params
/// already present in `params`.
pub async fn load_users_full(
    c: &tokio_postgres::Client,
    ids: Option<&[i32]>,
    where_sql: &str,
    params: &[&(dyn ToSql + Sync)],
) -> Result<Vec<User>, tokio_postgres::Error> {
    let sql = format!(
        "SELECT {} FROM users u JOIN persons p ON p.id = u.id {} {} ORDER BY p.id",
        USER_COLS_FULL,
        if ids.is_some() { "AND u.id = ANY($1)" } else { "" },
        where_sql
    );
    // rebuild: we need ids param first when present
    let sql = if ids.is_some() {
        format!(
            "SELECT {} FROM users u JOIN persons p ON p.id = u.id WHERE u.id = ANY($1) {} ORDER BY p.id",
            USER_COLS_FULL, where_sql
        )
    } else {
        format!(
            "SELECT {} FROM users u JOIN persons p ON p.id = u.id {} ORDER BY p.id",
            USER_COLS_FULL, where_sql
        )
    };
    let _ = sql.clone();
    let rows = c.query(&sql, params).await?;
    let mut users: Vec<User> = rows.iter().map(user_from_joined_row).collect();
    if !users.is_empty() {
        attach_user_collections(c, &mut users).await?;
    }
    Ok(users)
}

/// Attach roles (full) and user-group ids to already-loaded users.
pub async fn attach_user_collections(
    c: &tokio_postgres::Client,
    users: &mut [User],
) -> Result<(), tokio_postgres::Error> {
    let ids: Vec<i32> = users.iter().filter_map(|u| u.id).collect();
    if ids.is_empty() {
        return Ok(());
    }
    let role_rows = c
        .query(
            "SELECT ur.user_id AS uid, r.id, r.created, r.modified, r.name, r.description
             FROM users_roles ur JOIN roles r ON r.id = ur.role_id
             WHERE ur.user_id = ANY($1) ORDER BY r.id",
            &[&ids],
        )
        .await?;
    let grp_rows = c
        .query(
            "SELECT user_id, usergroup_id FROM user_usergroup WHERE user_id = ANY($1) ORDER BY usergroup_id",
            &[&ids],
        )
        .await?;
    let mut roles_by_user: std::collections::HashMap<i32, Vec<Role>> = Default::default();
    for r in &role_rows {
        let uid: i32 = r.get("uid");
        roles_by_user.entry(uid).or_default().push(role_from_row(r));
    }
    let mut groups_by_user: std::collections::HashMap<i32, Vec<i32>> = Default::default();
    for r in &grp_rows {
        let uid: i32 = r.get("user_id");
        groups_by_user.entry(uid).or_default().push(r.get("usergroup_id"));
    }
    for u in users.iter_mut() {
        if let Some(id) = u.id {
            u.roles = roles_by_user.remove(&id).unwrap_or_default();
            u.user_group_ids = groups_by_user.remove(&id).unwrap_or_default();
        }
    }
    Ok(())
}

/// Load users with a restricted projection (output:only). `fields` are the
/// canonical (camelCase) field names to project.
pub async fn load_users_restricted(
    c: &tokio_postgres::Client,
    fields: &[String],
    where_sql: &str,
    params: &[&(dyn ToSql + Sync)],
) -> Result<Vec<User>, String> {
    let mut sel = Vec::new();
    for f in fields {
        let col = field_column(ResourceType::Users, f).ok_or("bad field")?;
        sel.push(format!("{} AS {}", col, pg_alias(f)));
    }
    let sql = format!(
        "SELECT {} FROM users u JOIN persons p ON p.id = u.id {} ORDER BY p.id",
        sel.join(", "),
        where_sql
    );
    let rows = c.query(&sql, params).await.map_err(|e| e.to_string())?;
    let mut out = Vec::new();
    for row in &rows {
        let mut u = User::new_fresh(); // created=now semantics for equals
        u.fresh = true;
        u.restricted = Some(fields.to_vec());
        for f in fields {
            let a = pg_alias(f);
            match f.as_str() {
                "id" => u.id = row.get::<_, Option<i32>>(&a[..]),
                "firstName" => u.first_name = row.get(&a[..]),
                "lastName" => u.last_name = row.get(&a[..]),
                "email" => u.email = row.get(&a[..]),
                "accountName" => u.account_name = row.get(&a[..]),
                "password" => u.password = row.get(&a[..]),
                "active" => u.active = row.get::<_, Option<bool>>(&a[..]).unwrap_or(false),
                _ => {}
            }
        }
        out.push(u);
    }
    Ok(out)
}

fn pg_alias(field: &str) -> String {
    format!("f_{}", field.to_lowercase())
}

pub async fn load_user_full_by_id(
    c: &tokio_postgres::Client,
    id: i32,
) -> Result<Option<User>, tokio_postgres::Error> {
    let sql = format!(
        "SELECT {} FROM users u JOIN persons p ON p.id = u.id WHERE u.id = $1",
        USER_COLS_FULL
    );
    let row = c.query_opt(&sql, &[&id]).await?;
    match row {
        None => Ok(None),
        Some(r) => {
            let mut u = user_from_joined_row(&r);
            attach_user_collections(c, std::slice::from_mut(&mut u)).await?;
            Ok(Some(u))
        }
    }
}

// ---------------------------------------------------------------------------
// Roles
// ---------------------------------------------------------------------------

pub async fn load_roles(
    c: &tokio_postgres::Client,
    ids: Option<&[i32]>,
    where_sql: &str,
    params: &[&(dyn ToSql + Sync)],
) -> Result<Vec<Role>, tokio_postgres::Error> {
    let sql = if ids.is_some() {
        format!(
            "SELECT id, created, modified, name, description FROM roles WHERE id = ANY($1) {} ORDER BY id",
            where_sql
        )
    } else {
        format!(
            "SELECT id, created, modified, name, description FROM roles {} ORDER BY id",
            where_sql
        )
    };
    let rows = c.query(&sql, params).await?;
    Ok(rows.iter().map(role_from_row).collect())
}

pub async fn load_roles_restricted(
    c: &tokio_postgres::Client,
    fields: &[String],
    where_sql: &str,
    params: &[&(dyn ToSql + Sync)],
) -> Result<Vec<Role>, String> {
    let mut sel = Vec::new();
    for f in fields {
        let col = field_column(ResourceType::Roles, f).ok_or("bad field")?;
        sel.push(format!("{} AS {}", col, pg_alias(f)));
    }
    let sql = format!("SELECT {} FROM roles {} ORDER BY id", sel.join(", "), where_sql);
    let rows = c.query(&sql, params).await.map_err(|e| e.to_string())?;
    let mut out = Vec::new();
    for row in &rows {
        let mut r = Role::new_fresh();
        r.restricted_placeholder();
        for f in fields {
            let a = pg_alias(f);
            match f.as_str() {
                "id" => r.id = row.get::<_, Option<i32>>(&a[..]),
                "name" => r.name = row.get(&a[..]),
                "description" => r.description = row.get(&a[..]),
                _ => {}
            }
        }
        out.push(r);
    }
    Ok(out)
}

// ---------------------------------------------------------------------------
// Groups
// ---------------------------------------------------------------------------

pub async fn load_groups(
    c: &tokio_postgres::Client,
    ids: Option<&[i32]>,
    where_sql: &str,
    params: &[&(dyn ToSql + Sync)],
) -> Result<Vec<UserGroup>, tokio_postgres::Error> {
    let sql = if ids.is_some() {
        format!(
            "SELECT id, created, modified, name, owner_id FROM usergroups WHERE id = ANY($1) {} ORDER BY id",
            where_sql
        )
    } else {
        format!("SELECT id, created, modified, name, owner_id FROM usergroups {} ORDER BY id", where_sql)
    };
    let rows = c.query(&sql, params).await?;
    let mut groups: Vec<UserGroup> = rows.iter().map(group_from_row).collect();
    let owner_ids: Vec<i32> = rows.iter().filter_map(|r| r.get::<_, Option<i32>>("owner_id")).collect();
    let gids: Vec<i32> = groups.iter().filter_map(|g| g.id).collect();
    attach_group_collections(c, &mut groups, &rows, &owner_ids, &gids).await?;
    Ok(groups)
}

async fn attach_group_collections(
    c: &tokio_postgres::Client,
    groups: &mut [UserGroup],
    rows: &[Row],
    owner_ids: &[i32],
    gids: &[i32],
) -> Result<(), tokio_postgres::Error> {
    if groups.is_empty() {
        return Ok(());
    }
    // owners
    let owners = if owner_ids.is_empty() {
        Vec::new()
    } else {
        load_users_full(c, Some(owner_ids), "", &[]).await?
    };
    // members
    let member_rows = c
        .query(
            "SELECT usergroup_id, user_id FROM user_usergroup WHERE usergroup_id = ANY($1) ORDER BY user_id",
            &[gids],
        )
        .await?;
    let member_ids: Vec<i32> = member_rows.iter().map(|r| r.get("user_id")).collect();
    let members = if member_ids.is_empty() {
        Vec::new()
    } else {
        load_users_full(c, Some(&member_ids), "", &[]).await?
    };
    // roles
    let role_rows = c
        .query(
            "SELECT ur.usergroup_id AS gid, r.id, r.created, r.modified, r.name, r.description
             FROM usergroups_roles ur JOIN roles r ON r.id = ur.role_id
             WHERE ur.usergroup_id = ANY($1) ORDER BY r.id",
            &[gids],
        )
        .await?;
    for g in groups.iter_mut() {
        let gid = match g.id {
            Some(v) => v,
            None => continue,
        };
        let owner_id: Option<i32> = rows
            .iter()
            .find(|r| r.get::<_, i32>("id") == gid)
            .and_then(|r| r.get::<_, Option<i32>>("owner_id"));
        if let Some(oid) = owner_id {
            g.owner = owners.iter().find(|u| u.id == Some(oid)).cloned().map(Box::new);
        }
        g.members = members
            .iter()
            .filter(|u| {
                member_rows.iter().any(|r| r.get::<_, i32>("usergroup_id") == gid && r.get::<_, i32>("user_id") == u.id.unwrap_or(-1))
            })
            .cloned()
            .collect();
        g.roles = role_rows
            .iter()
            .filter(|r| r.get::<_, i32>("gid") == gid)
            .map(role_from_row)
            .collect();
    }
    Ok(())
}

pub async fn load_groups_restricted(
    c: &tokio_postgres::Client,
    fields: &[String],
    where_sql: &str,
    params: &[&(dyn ToSql + Sync)],
) -> Result<Vec<UserGroup>, String> {
    let mut sel = Vec::new();
    for f in fields {
        let col = field_column(ResourceType::Groups, f).ok_or("bad field")?;
        sel.push(format!("{} AS {}", col, pg_alias(f)));
    }
    let sql = format!("SELECT {} FROM usergroups {} ORDER BY usergroups.id", sel.join(", "), where_sql);
    let rows = c.query(&sql, params).await.map_err(|e| e.to_string())?;
    let mut out = Vec::new();
    for row in &rows {
        let mut g = UserGroup::new_fresh();
        g.restricted = Some(fields.to_vec());
        for f in fields {
            let a = pg_alias(f);
            match f.as_str() {
                "id" => g.id = row.get::<_, Option<i32>>(&a[..]),
                "name" => g.name = row.get(&a[..]),
                _ => {}
            }
        }
        out.push(g);
    }
    Ok(out)
}

// ---------------------------------------------------------------------------
// Layers, appearances, data sources, tile grids, extents
// ---------------------------------------------------------------------------

pub async fn load_layers(
    c: &tokio_postgres::Client,
    ids: Option<&[i32]>,
    where_sql: &str,
    params: &[&(dyn ToSql + Sync)],
) -> Result<Vec<Layer>, tokio_postgres::Error> {
    let sql = if ids.is_some() {
        format!(
            "SELECT id, created, modified, description, name, appearance_id, source_id FROM layers WHERE id = ANY($1) {} ORDER BY id",
            where_sql
        )
    } else {
        format!(
            "SELECT id, created, modified, description, name, appearance_id, source_id FROM layers {} ORDER BY id",
            where_sql
        )
    };
    let rows = c.query(&sql, params).await?;
    let mut layers: Vec<Layer> = rows.iter().map(layer_from_row).collect();
    if layers.is_empty() {
        return Ok(layers);
    }
    let source_ids: Vec<i32> = rows.iter().filter_map(|r| r.get::<_, Option<i32>>("source_id")).collect();
    let app_ids: Vec<i32> = rows.iter().filter_map(|r| r.get::<_, Option<i32>>("appearance_id")).collect();
    let sources = if source_ids.is_empty() { Vec::new() } else { load_datasources(c, &source_ids).await? };
    let apps = if app_ids.is_empty() { Vec::new() } else { load_appearances(c, &app_ids).await? };
    for (l, r) in layers.iter_mut().zip(rows.iter()) {
        if let Some(sid) = r.get::<_, Option<i32>>("source_id") {
            l.source = sources.iter().find(|d| d.id == Some(sid)).cloned().map(Box::new);
        }
        if let Some(aid) = r.get::<_, Option<i32>>("appearance_id") {
            l.appearance = apps.iter().find(|a| a.id == Some(aid)).cloned().map(Box::new);
        }
    }
    Ok(layers)
}

pub async fn load_layers_restricted(
    c: &tokio_postgres::Client,
    fields: &[String],
    where_sql: &str,
    params: &[&(dyn ToSql + Sync)],
) -> Result<Vec<Layer>, String> {
    let mut sel = Vec::new();
    for f in fields {
        let col = field_column(ResourceType::Layers, f).ok_or("bad field")?;
        sel.push(format!("{} AS {}", col, pg_alias(f)));
    }
    let sql = format!("SELECT {} FROM layers {} ORDER BY layers.id", sel.join(", "), where_sql);
    let rows = c.query(&sql, params).await.map_err(|e| e.to_string())?;
    let mut out = Vec::new();
    for row in &rows {
        let mut l = Layer::new_fresh();
        l.restricted = Some(fields.to_vec());
        for f in fields {
            let a = pg_alias(f);
            match f.as_str() {
                "id" => l.id = row.get::<_, Option<i32>>(&a[..]),
                "name" => l.name = row.get(&a[..]),
                "description" => l.description = row.get(&a[..]),
                _ => {}
            }
        }
        out.push(l);
    }
    Ok(out)
}

pub async fn load_appearances(
    c: &tokio_postgres::Client,
    ids: Option<&[i32]>,
    where_sql: &str,
    params: &[&(dyn ToSql + Sync)],
) -> Result<Vec<LayerAppearance>, tokio_postgres::Error> {
    let sql = if ids.is_some() {
        format!(
            "SELECT id, created, modified, attribution, clickable, hovertemplate, hoverable, \
             maxresolution, minresolution, name, opacity, visible \
             FROM layerappearances WHERE id = ANY($1) {} ORDER BY id",
            where_sql
        )
    } else {
        format!(
            "SELECT id, created, modified, attribution, clickable, hovertemplate, hoverable, \
             maxresolution, minresolution, name, opacity, visible \
             FROM layerappearances {} ORDER BY id",
            where_sql
        )
    };
    let rows = c.query(&sql, params).await?;
    let mut apps: Vec<LayerAppearance> = rows.iter().map(appearance_from_row).collect();
    let aids: Vec<i32> = apps.iter().filter_map(|a| a.id).collect();
    if !aids.is_empty() {
        let prop_rows = c
            .query(
                "SELECT appearance_id, property, value FROM layerappearances_properties WHERE appearance_id = ANY($1) ORDER BY property",
                &[&aids],
            )
            .await?;
        for a in apps.iter_mut() {
            let aid = a.id.unwrap_or(-1);
            a.properties = prop_rows
                .iter()
                .filter(|r| r.get::<_, i32>("appearance_id") == aid)
                .map(|r| {
                    let key: String = r.get("property");
                    let val: Option<String> = r.get("value");
                    (key.clone(), match val {
                        Some(s) => PropValue::from_db_string(&s),
                        None => PropValue::Str("null".to_string()),
                    })
                })
                .collect();
        }
    }
    Ok(apps)
}

pub async fn load_appearances_restricted(
    c: &tokio_postgres::Client,
    fields: &[String],
    where_sql: &str,
    params: &[&(dyn ToSql + Sync)],
) -> Result<Vec<LayerAppearance>, String> {
    let mut sel = Vec::new();
    for f in fields {
        let col = field_column(ResourceType::Appearances, f).ok_or("bad field")?;
        sel.push(format!("{} AS {}", col, pg_alias(f)));
    }
    let sql = format!(
        "SELECT {} FROM layerappearances {} ORDER BY layerappearances.id",
        sel.join(", "),
        where_sql
    );
    let rows = c.query(&sql, params).await.map_err(|e| e.to_string())?;
    let mut out = Vec::new();
    for row in &rows {
        let mut a = LayerAppearance::new_fresh();
        a.restricted = Some(fields.to_vec());
        a.properties_raw = None; // loaded-style: properties serialize as {}
        for f in fields {
            let al = pg_alias(f);
            match f.as_str() {
                "id" => a.id = row.get::<_, Option<i32>>(&al[..]),
                "attribution" => a.attribution = row.get(&al[..]),
                "hoverable" => a.hoverable = row.get(&al[..]),
                "clickable" => a.clickable = row.get(&al[..]),
                "hoverTemplate" => a.hover_template = row.get(&al[..]),
                "name" => a.name = row.get(&al[..]),
                "maxResolution" => a.max_resolution = row.get(&al[..]),
                "minResolution" => a.min_resolution = row.get(&al[..]),
                "opacity" => a.opacity = row.get(&al[..]),
                "visible" => a.visible = row.get(&al[..]),
                _ => {}
            }
        }
        out.push(a);
    }
    Ok(out)
}

pub async fn load_datasources(
    c: &tokio_postgres::Client,
    ids: &[i32],
) -> Result<Vec<DataSource>, String> {
    let sql = format!("{} WHERE d.id = ANY($1) ORDER BY d.id", DS_SELECT);
    let rows = c.query(&sql, &[&ids]).await.map_err(|e| e.to_string())?;
    datasources_from_rows(c, &rows).await
}

pub async fn load_datasources_where(
    c: &tokio_postgres::Client,
    where_sql: &str,
    params: &[&(dyn ToSql + Sync)],
) -> Result<Vec<DataSource>, String> {
    let sql = format!("{} {} ORDER BY d.id", DS_SELECT, where_sql);
    let rows = c.query(&sql, params).await.map_err(|e| e.to_string())?;
    datasources_from_rows(c, &rows).await
}

async fn datasources_from_rows(
    c: &tokio_postgres::Client,
    rows: &[Row],
) -> Result<Vec<DataSource>, String> {
    let mut dss: Vec<DataSource> = Vec::new();
    let mut tilegrid_ids: Vec<i32> = Vec::new();
    let mut xyz_extent_ids: Vec<i32> = Vec::new();
    let mut wmts_ids: Vec<i32> = Vec::new();
    let mut xyz_ids: Vec<i32> = Vec::new();
    for row in rows {
        let mut ds = datasource_from_row(row);
        datasource_fix_wfs_version(&mut ds, row);
        match ds.kind {
            DsKind::TileWms => {
                if let Some(gid) = row.get::<_, Option<i32>>("tw_tilegrid_id") {
                    tilegrid_ids.push(gid);
                    ds.tile_grid = Some(Box::new(TileGrid::from_db(false)));
                    ds.tile_grid.as_mut().unwrap().id = Some(gid);
                }
            }
            DsKind::Wmts => {
                wmts_ids.push(ds.id.unwrap_or(-1));
                if let Some(gid) = row.get::<_, Option<i32>>("wmts_tilegrid_id") {
                    tilegrid_ids.push(gid);
                    ds.tile_grid = Some(Box::new(TileGrid::from_db(true)));
                    ds.tile_grid.as_mut().unwrap().id = Some(gid);
                }
            }
            DsKind::Xyz => {
                xyz_ids.push(ds.id.unwrap_or(-1));
                if let Some(eid) = row.get::<_, Option<i32>>("xyz_extent_id") {
                    xyz_extent_ids.push(eid);
                }
            }
            _ => {}
        }
        dss.push(ds);
    }
    // tile grids (full)
    let grids = load_tilegrids(c, &tilegrid_ids).await?;
    // wmts urls
    let url_rows = if wmts_ids.is_empty() {
        Vec::new()
    } else {
        c.query(
            "SELECT wmtslayerdatasources_id, urls FROM wmtslayerdatasources_urls WHERE wmtslayerdatasources_id = ANY($1)",
            &[&wmts_ids],
        )
        .await
        .map_err(|e| e.to_string())?
    };
    // xyz extents + resolutions
    let xyz_extents = load_extents(c, &xyz_extent_ids).await?;
    let res_rows = if xyz_ids.is_empty() {
        Vec::new()
    } else {
        c.query(
            "SELECT xyzlayerdatasrc_id, resolution, idx FROM xyzlayerdatasrc_resolution WHERE xyzlayerdatasrc_id = ANY($1) ORDER BY idx",
            &[&xyz_ids],
        )
        .await
        .map_err(|e| e.to_string())?
    };
    for ds in dss.iter_mut() {
        let id = ds.id.unwrap_or(-1);
        match ds.kind {
            DsKind::TileWms | DsKind::Wmts => {
                let gid = ds.tile_grid.as_ref().and_then(|g| g.id);
                if let Some(gid) = gid {
                    if let Some(g) = grids.iter().find(|g| g.id == Some(gid)) {
                        ds.tile_grid = Some(Box::new(g.clone()));
                    }
                }
                if ds.kind == DsKind::Wmts {
                    ds.urls = Some(
                        url_rows
                            .iter()
                            .filter(|r| r.get::<_, i32>("wmtslayerdatasources_id") == id)
                            .map(|r| r.get::<_, Option<String>>("urls"))
                            .collect(),
                    );
                }
            }
            DsKind::Xyz => {
                if let Some(row) = rows.iter().find(|r| r.get::<_, i32>("id") == id) {
                    if let Some(eid) = row.get::<_, Option<i32>>("xyz_extent_id") {
                        ds.extent = xyz_extents.iter().find(|e| e.id == Some(eid)).cloned().map(Box::new);
                    }
                }
                let mut list = Vec::new();
                for r in res_rows.iter().filter(|r| r.get::<_, i32>("xyzlayerdatasrc_id") == id) {
                    let blob: Option<Vec<u8>> = r.get("resolution");
                    if let Some(b) = blob {
                        if let Some((x, y)) = javadoc::deserialize_point2d_double(&b) {
                            list.push(Point { x, y });
                        }
                    }
                }
                ds.resolutions = Some(list);
            }
            _ => {}
        }
    }
    Ok(dss)
}

pub async fn load_tilegrids(
    c: &tokio_postgres::Client,
    ids: &[i32],
) -> Result<Vec<TileGrid>, String> {
    if ids.is_empty() {
        return Ok(Vec::new());
    }
    let rows = c
        .query(
            "SELECT g.id, g.created, g.modified, g.type, g.tilegridorigin_x, g.tilegridorigin_y, \
             g.tilesize, g.tilegridextent_id, (w.id IS NOT NULL) AS is_wmts \
             FROM tilegrids g LEFT JOIN wmtstilegrids w ON w.id = g.id WHERE g.id = ANY($1) ORDER BY g.id",
            &[&ids],
        )
        .await
        .map_err(|e| e.to_string())?;
    let mut grids: Vec<TileGrid> = rows
        .iter()
        .map(|r| {
            let is_wmts: bool = r.get("is_wmts");
            tilegrid_from_row(r, is_wmts)
        })
        .collect();
    // resolutions
    let res_rows = c
        .query(
            "SELECT tilegrid_id, resolution, idx FROM tilegrid_resolution WHERE tilegrid_id = ANY($1) ORDER BY idx",
            &[&ids],
        )
        .await
        .map_err(|e| e.to_string())?;
    // matrix ids
    let wids: Vec<i32> = grids.iter().filter(|g| g.is_wmts).filter_map(|g| g.id).collect();
    let mat_rows = if wids.is_empty() {
        Vec::new()
    } else {
        c.query(
            "SELECT wmtstilegrids_id, matrixids FROM wmtstilegrids_matrixids WHERE wmtstilegrids_id = ANY($1)",
            &[&wids],
        )
        .await
        .map_err(|e| e.to_string())?
    };
    // extents
    let ext_ids: Vec<i32> = rows.iter().filter_map(|r| r.get::<_, Option<i32>>("tilegridextent_id")).collect();
    let extents = load_extents(c, &ext_ids).await?;
    for (g, r) in grids.iter_mut().zip(rows.iter()) {
        let gid = g.id.unwrap_or(-1);
        g.resolutions = Some(
            res_rows
                .iter()
                .filter(|rr| rr.get::<_, i32>("tilegrid_id") == gid)
                .map(|rr| rr.get::<_, Option<f64>>("resolution").unwrap_or(0.0))
                .collect(),
        );
        if g.is_wmts {
            g.matrix_ids = Some(
                mat_rows
                    .iter()
                    .filter(|rr| rr.get::<_, i32>("wmtstilegrids_id") == gid)
                    .map(|rr| rr.get::<_, Option<String>>("matrixids"))
                    .collect(),
            );
        }
        if let Some(eid) = r.get::<_, Option<i32>>("tilegridextent_id") {
            g.extent = extents.iter().find(|e| e.id == Some(eid)).cloned().map(Box::new);
        }
    }
    Ok(grids)
}

pub async fn load_extents(
    c: &tokio_postgres::Client,
    ids: &[i32],
) -> Result<Vec<Extent>, String> {
    if ids.is_empty() {
        return Ok(Vec::new());
    }
    let rows = c
        .query(
            "SELECT id, created, modified, lowerleft_x, lowerleft_y, upperright_x, upperright_y \
             FROM extents WHERE id = ANY($1) ORDER BY id",
            &[&ids],
        )
        .await
        .map_err(|e| e.to_string())?;
    Ok(rows.iter().map(extent_from_row).collect())
}

pub async fn load_extent_by_id(
    c: &tokio_postgres::Client,
    id: i32,
) -> Result<Option<Extent>, String> {
    let v = load_extents(c, &[id]).await?;
    Ok(v.into_iter().next())
}

pub async fn exists(
    c: &tokio_postgres::Client,
    table: &str,
    id: i32,
) -> Result<bool, tokio_postgres::Error> {
    let sql = format!("SELECT 1 FROM {} WHERE id = $1", table);
    Ok(c.query_opt(&sql, &[&id]).await?.is_some())
}

