pub struct AuthRow {
    pub id: i32,
    pub account_name: Option<String>,
    pub active: bool,
    pub password: Option<String>,
}

pub async fn find_auth_user(
    c: &tokio_postgres::Client,
    account_name: &str,
) -> Result<Option<AuthRow>, tokio_postgres::Error> {
    let row = c
        .query_opt(
            "SELECT id, accountname, active, password FROM users WHERE accountname = $1",
            &[&account_name],
        )
        .await?;
    Ok(row.map(|r| AuthRow {
        id: r.get("id"),
        account_name: r.get("accountname"),
        active: r.get::<_, Option<bool>>("active").unwrap_or(false),
        password: r.get("password"),
    }))
}

pub async fn load_role_names(
    c: &tokio_postgres::Client,
    user_id: i32,
) -> Result<Vec<String>, tokio_postgres::Error> {
    let rows = c
        .query(
            "SELECT r.name FROM users_roles ur JOIN roles r ON r.id = ur.role_id WHERE ur.user_id = $1
             UNION
             SELECT r.name FROM usergroups_roles gr
               JOIN user_usergroup ug ON ug.usergroup_id = gr.usergroup_id
               JOIN roles r ON r.id = gr.role_id
             WHERE ug.user_id = $1",
            &[&user_id],
        )
        .await?;
    Ok(rows.iter().map(|r| r.get::<_, String>("name")).collect())
}

pub async fn load_memberships(
    c: &tokio_postgres::Client,
    user_id: i32,
) -> Result<Vec<i32>, tokio_postgres::Error> {
    let rows = c
        .query("SELECT usergroup_id FROM user_usergroup WHERE user_id = $1", &[&user_id])
        .await?;
    Ok(rows.iter().map(|r| r.get("usergroup_id")).collect())
}

pub async fn load_principal_perms(
    c: &tokio_postgres::Client,
    user_id: i32,
    member_of: &[i32],
) -> Result<PrincipalPerms, tokio_postgres::Error> {
    let mut perms = PrincipalPerms { user_perms: Default::default(), group_perms: Default::default(), member_of: member_of.to_vec() };
    let rows = c
        .query(
            "SELECT up.entity_id AS entity_id, pcp.permissions AS permissions
             FROM userpermissions up
             JOIN permissioncollections_permissions pcp ON pcp.permissioncollections_id = up.userpermissions_id
             WHERE up.userpermissions_key = $1",
            &[&user_id],
        )
        .await?;
    for r in &rows {
        let eid: i32 = r.get("entity_id");
        let p: Option<String> = r.get("permissions");
        if let Some(p) = p {
            if let Some(perm) = Permission::from_string(&p) {
                perms.user_perms.entry(eid).or_default().push(perm);
            }
        }
    }
    if !member_of.is_empty() {
        let rows = c
            .query(
                "SELECT gp.entity_id AS entity_id, pcp.permissions AS permissions
                 FROM grouppermissions gp
                 JOIN permissioncollections_permissions pcp ON pcp.permissioncollections_id = gp.grouppermissions_id
                 WHERE gp.grouppermissions_key = ANY($1)",
                &[&member_of],
            )
            .await?;
        for r in &rows {
            let eid: i32 = r.get("entity_id");
            let p: Option<String> = r.get("permissions");
            if let Some(p) = p {
                if let Some(perm) = Permission::from_string(&p) {
                    perms.group_perms.entry(eid).or_default().push(perm);
                }
            }
        }
    }
    Ok(perms)
}

