{"content": "//! Database access: connection pool, entity loading (full / restricted /
//! filtered), id allocation from `hibernate_sequences` and all writes,
//! mirroring what Hibernate does in the original.

use chrono::{Local, NaiveDateTime};
use deadpool_postgres::{Config as DpConfig, Pool, Runtime};
use tokio_postgres::types::ToSql;
use tokio_postgres::{NoTls, Row};

use crate::model::*;

pub fn create_pool(database_url: &str) -> Result<Pool, String> {
    let mut pg_cfg = tokio_postgres::Config::from_str(database_url)
        .map_err(|e| format!("invalid DATABASE_URL: {}", e))?;
    // keep default application_name quiet
    let _ = &mut pg_cfg;
    let mut cfg = DpConfig::from(pg_cfg.clone());
    cfg.pool = Some(deadpool_postgres::PoolConfig::default());
    let manager = cfg.create_manager(Some(Runtime::Tokio1));
    let pool = Pool::builder(manager)
        .max_size(8)
        .build()
        .map_err(|e| format!("pool build error: {}", e))?;
    Ok(pool)
}

pub fn now() -> NaiveDateTime {
    Local::now().naive_local()
}

/// Allocate the next id the way Hibernate's TableGenerator does:
/// new id = next_val + 1, then next_val = new id. Executed with autocommit so
/// the value is consumed even if the surrounding business transaction rolls
/// back (matching the original).
pub async fn next_id(pool: &Pool) -> Result<i32, String> {
    let c = pool.get().await.map_err(|e| e.to_string())?;
    let row = c
        .query_one(
            "INSERT INTO hibernate_sequences (sequence_name, next_val) VALUES ('default', 1)
             ON CONFLICT (sequence_name)
             DO UPDATE SET next_val = COALESCE(hibernate_sequences.next_val, 0) + 1
             RETURNING next_val",
            &[],
        )
        .await
        .map_err(|e| e.to_string())?;
    let v: i64 = row.get("next_val");
    Ok(v as i32)
}

pub struct DynQuery {
    pub sql: String,
    pub params: Vec<Box<dyn ToSql + Sync>>,
}

impl DynQuery {
    pub fn refs(&self) -> Vec<&(dyn ToSql + Sync)> {
        self.params.iter().map(|b| b.as_ref() as &(dyn ToSql + Sync)).collect()
    }
}

// ---------------------------------------------------------------------------
// Users
// ---------------------------------------------------------------------------

const USER_COLS_FULL: &str = "p.id AS u_id, p.created AS u_created, p.modified AS u_modified, \
     p.birthday AS u_birthday, p.email AS u_email, p.firstname AS u_firstname, \
     p.language AS u_language, p.lastname AS u_lastname, \
     u.accountname AS u_accountname, u.active AS u_active, u.password AS u_password";

/// Load users (full entities incl. roles and group ids).
/// `ids`: restrict to these ids; `filter`: extra WHERE clause with $n params
/// already present in `params`.
pub async fn load_users_full(
    c: &tokio_postgres::Client,
    ids: Option<&[i32]>,
    where_sql: &str,
    params: &[&(dyn ToSql + Sync)],
) -> Result<Vec<User>, tokio_postgres::Error> {
    let sql = format!(
        "SELECT {} FROM users u JOIN persons p ON p.id = u.id {} {} ORDER BY p.id",
        USER_COLS_FULL,
        if ids.is_some() { "AND u.id = ANY($1)" } else { "" },
        where_sql
    );
    // rebuild: we need ids param first when present
    let sql = if ids.is_some() {
        format!(
            "SELECT {} FROM users u JOIN persons p ON p.id = u.id WHERE u.id = ANY($1) {} ORDER BY p.id",
            USER_COLS_FULL, where_sql
        )
    } else {
        format!(
            "SELECT {} FROM users u JOIN persons p ON p.id = u.id {} ORDER BY p.id",
            USER_COLS_FULL, where_sql
        )
    };
    let _ = sql.clone();
    let rows = c.query(&sql, params).await?;
    let mut users: Vec<User> = rows.iter().map(user_from_joined_row).collect();
    if !users.is_empty() {
        attach_user_collections(c, &mut users).await?;
    }
    Ok(users)
}

/// Attach roles (full) and user-group ids to already-loaded users.
pub async fn attach_user_collections(
    c: &tokio_postgres::Client,
    users: &mut [User],
) -> Result<(), tokio_postgres::Error> {
    let ids: Vec<i32> = users.iter().filter_map(|u| u.id).collect();
    if ids.is_empty() {
        return Ok(());
    }
    let role_rows = c
        .query(
            "SELECT ur.user_id AS uid, r.id, r.created, r.modified, r.name, r.description
             FROM users_roles ur JOIN roles r ON r.id = ur.role_id
             WHERE ur.user_id = ANY($1) ORDER BY r.id",
            &[&ids],
        )
        .await?;
    let grp_rows = c
        .query(
            "SELECT user_id, usergroup_id FROM user_usergroup WHERE user_id = ANY($1) ORDER BY usergroup_id",
            &[&ids],
        )
        .await?;
    let mut roles_by_user: std::collections::HashMap<i32, Vec<Role>> = Default::default();
    for r in &role_rows {
        let uid: i32 = r.get("uid");
        roles_by_user.entry(uid).or_default().push(role_from_row(r));
    }
    let mut groups_by_user: std::collections::HashMap<i32, Vec<i32>> = Default::default();
    for r in &grp_rows {
        let uid: i32 = r.get("user_id");
        groups_by_user.entry(uid).or_default().push(r.get("usergroup_id"));
    }
    for u in users.iter_mut() {
        if let Some(id) = u.id {
            u.roles = roles_by_user.remove(&id).unwrap_or_default();
            u.user_group_ids = groups_by_user.remove(&id).unwrap_or_default();
        }
    }
    Ok(())
}

/// Load users with a restricted projection (output:only). `fields` are the
/// canonical (camelCase) field names to project.
pub async fn load_users_restricted(
    c: &tokio_postgres::Client,
    fields: &[String],
    where_sql: &str,
    params: &[&(dyn ToSql + Sync)],
) -> Result<Vec<User>, String> {
    let mut sel = Vec::new();
    for f in fields {
        let col = field_column(ResourceType::Users, f).ok_or("bad field")?;
        sel.push(format!("{} AS {}", col, pg_alias(f)));
    }
    let sql = format!(
        "SELECT {} FROM users u JOIN persons p ON p.id = u.id {} ORDER BY p.id",
        sel.join(", "),
        where_sql
    );
    let rows = c.query(&sql, params).await.map_err(|e| e.to_string())?;
    let mut out = Vec::new();
    for row in &rows {
        let mut u = User::new_fresh(); // created=now semantics for equals
        u.fresh = true;
        u.restricted = Some(fields.to_vec());
        for f in fields {
            let a = pg_alias(f);
            match f.as_str() {
                "id" => u.id = row.get::<_, Option<i32>>(&a[..]),
                "firstName" => u.first_name = row.get(&a[..]),
                "lastName" => u.last_name = row.get(&a[..]),
                "email" => u.email = row.get(&a[..]),
                "accountName" => u.account_name = row.get(&a[..]),
                "password" => u.password = row.get(&a[..]),
                "active" => u.active = row.get::<_, Option<bool>>(&a[..]).unwrap_or(false),
                _ => {}
            }
        }
        out.push(u);
    }
    Ok(out)
}

fn pg_alias(field: &str) -> String {
    format!("f_{}", field.to_lowercase())
}

pub async fn load_user_full_by_id(
    c: &tokio_postgres::Client,
    id: i32,
) -> Result<Option<User>, tokio_postgres::Error> {
    let sql = format!(
        "SELECT {} FROM users u JOIN persons p ON p.id = u.id WHERE u.id = $1",
        USER_COLS_FULL
    );
    let row = c.query_opt(&sql, &[&id]).await?;
    match row {
        None => Ok(None),
        Some(r) => {
            let mut u = user_from_joined_row(&r);
            attach_user_collections(c, std::slice::from_mut(&mut u)).await?;
            Ok(Some(u))
        }
    }
}

// ---------------------------------------------------------------------------
// Roles
// ---------------------------------------------------------------------------

pub async fn load_roles(
    c: &tokio_postgres::Client,
    ids: Option<&[i32]>,
    where_sql: &str,
    params: &[&(dyn ToSql + Sync)],
) -> Result<Vec<Role>, tokio_postgres::Error> {
    let sql = if ids.is_some() {
        format!(
            "SELECT id, created, modified, name, description FROM roles WHERE id = ANY($1) {} ORDER BY id",
            where_sql
        )
    } else {
        format!(
            "SELECT id, created, modified, name, description FROM roles {} ORDER BY id",
            where_sql
        )
    };
    let rows = c.query(&sql, params).await?;
    Ok(rows.iter().map(role_from_row).collect())
}

pub async fn load_roles_restricted(
    c: &tokio_postgres::Client,
    fields: &[String],
    where_sql: &str,
    params: &[&(dyn ToSql + Sync)],
) -> Result<Vec<Role>, String> {
    let mut sel = Vec::new();
    for f in fields {
        let col = field_column(ResourceType::Roles, f).ok_or("bad field")?;
        sel.push(format!("{} AS {}", col, pg_alias(f)));
    }
    let sql = format!("SELECT {} FROM roles {} ORDER BY id", sel.join(", "), where_sql);
    let rows = c.query(&sql, params).await.map_err(|e| e.to_string())?;
    let mut out = Vec::new();
    for row in &rows {
        let mut r = Role::new_fresh();
        r.restricted_placeholder();
        for f in fields {
            let a = pg_alias(f);
            match f.as_str() {
                "id" => r.id = row.get::<_, Option<i32>>(&a[..]),
                "name" => r.name = row.get(&a[..]),
                "description" => r.description = row.get(&a[..]),
                _ => {}
            }
        }
        out.push(r);
    }
    Ok(out)
}

// ---------------------------------------------------------------------------
// Groups
// ---------------------------------------------------------------------------

pub async fn load_groups(
    c: &tokio_postgres::Client,
    ids: Option<&[i32]>,
    where_sql: &str,
    params: &[&(dyn ToSql + Sync)],
) -> Result<Vec<UserGroup>, tokio_postgres::Error> {
    let sql = if ids.is_some() {
        format!(
            "SELECT id, created, modified, name, owner_id FROM usergroups WHERE id = ANY($1) {} ORDER BY id",
            where_sql
        )
    } else {
        format!("SELECT id, created, modified, name, owner_id FROM usergroups {} ORDER BY id", where_sql)
    };
    let rows = c.query(&sql, params).await?;
    let mut groups: Vec<UserGroup> = rows.iter().map(group_from_row).collect();
    let owner_ids: Vec<i32> = rows.iter().filter_map(|r| r.get::<_, Option<i32>>("owner_id")).collect();
    let gids: Vec<i32> = groups.iter().filter_map(|g| g.id).collect();
    attach_group_collections(c, &mut groups, &rows, &owner_ids, &gids).await?;
    Ok(groups)
}

async fn attach_group_collections(
    c: &tokio_postgres::Client,
    groups: &mut [UserGroup],
    rows: &[Row],
    owner_ids: &[i32],
    gids: &[i32],
) -> Result<(), tokio_postgres::Error> {
    if groups.is_empty() {
        return Ok(());
    }
    // owners
    let owners = if owner_ids.is_empty() {
        Vec::new()
    } else {
        load_users_full(c, Some(owner_ids), "", &[]).await?
    };
    // members
    let member_rows = c
        .query(
            "SELECT usergroup_id, user_id FROM user_usergroup WHERE usergroup_id = ANY($1) ORDER BY user_id",
            &[gids],
        )
        .await?;
    let member_ids: Vec<i32> = member_rows.iter().map(|r| r.get("user_id")).collect();
    let members = if member_ids.is_empty() {
        Vec::new()
    } else {
        load_users_full(c, Some(&member_ids), "", &[]).await?
    };
    // roles
    let role_rows = c
        .query(
            "SELECT ur.usergroup_id AS gid, r.id, r.created, r.modified, r.name, r.description
             FROM usergroups_roles ur JOIN roles r ON r.id = ur.role_id
             WHERE ur.usergroup_id = ANY($1) ORDER BY r.id",
            &[gids],
        )
        .await?;
    for g in groups.iter_mut() {
        let gid = match g.id {
            Some(v) => v,
            None => continue,
        };
        let owner_id: Option<i32> = rows
            .iter()
            .find(|r| r.get::<_, i32>("id") == gid)
            .and_then(|r| r.get::<_, Option<i32>>("owner_id"));
        if let Some(oid) = owner_id {
            g.owner = owners.iter().find(|u| u.id == Some(oid)).cloned().map(Box::new);
        }
        g.members = members
            .iter()
            .filter(|u| {
                member_rows.iter().any(|r| r.get::<_, i32>("usergroup_id") == gid && r.get::<_, i32>("user_id") == u.id.unwrap_or(-1))
            })
            .cloned()
            .collect();
        g.roles = role_rows
            .iter()
            .filter(|r| r.get::<_, i32>("gid") == gid)
            .map(role_from_row)
            .collect();
    }
    Ok(())
}

