pub async fn load_layers(
    c: &tokio_postgres::Client,
    ids: Option<&[i32]>,
    where_sql: &str,
    params: &[&(dyn ToSql + Sync)],
) -> Result<Vec<Layer>, tokio_postgres::Error> {
    let sql = if ids.is_some() {
        format!(
            "SELECT id, created, modified, description, name, appearance_id, source_id FROM layers WHERE id = ANY($1) {} ORDER BY id",
            where_sql
        )
    } else {
        format!(
            "SELECT id, created, modified, description, name, appearance_id, source_id FROM layers {} ORDER BY id",
            where_sql
        )
    };
    let rows = c.query(&sql, params).await?;
    let mut layers: Vec<Layer> = rows.iter().map(layer_from_row).collect();
    if layers.is_empty() {
        return Ok(layers);
    }
    let source_ids: Vec<i32> = rows.iter().filter_map(|r| r.get::<_, Option<i32>>("source_id")).collect();
    let app_ids: Vec<i32> = rows.iter().filter_map(|r| r.get::<_, Option<i32>>("appearance_id")).collect();
    let sources = if source_ids.is_empty() { Vec::new() } else { load_datasources(c, &source_ids).await? };
    let apps = if app_ids.is_empty() { Vec::new() } else { load_appearances(c, &app_ids).await? };
    for (l, r) in layers.iter_mut().zip(rows.iter()) {
        if let Some(sid) = r.get::<_, Option<i32>>("source_id") {
            l.source = sources.iter().find(|d| d.id == Some(sid)).cloned().map(Box::new);
        }
        if let Some(aid) = r.get::<_, Option<i32>>("appearance_id") {
            l.appearance = apps.iter().find(|a| a.id == Some(aid)).cloned().map(Box::new);
        }
    }
    Ok(layers)
}

