pub async fn load_appearances(
    c: &tokio_postgres::Client,
    ids: Option<&[i32]>,
    where_sql: &str,
    params: &[&(dyn ToSql + Sync)],
) -> Result<Vec<LayerAppearance>, tokio_postgres::Error> {
    let sql = if ids.is_some() {
        format!(
            "SELECT id, created, modified, attribution, clickable, hovertemplate, hoverable, \
             maxresolution, minresolution, name, opacity, visible \
             FROM layerappearances WHERE id = ANY($1) {} ORDER BY id",
            where_sql
        )
    } else {
        format!(
            "SELECT id, created, modified, attribution, clickable, hovertemplate, hoverable, \
             maxresolution, minresolution, name, opacity, visible \
             FROM layerappearances {} ORDER BY id",
            where_sql
        )
    };
    let rows = c.query(&sql, params).await?;
    let mut apps: Vec<LayerAppearance> = rows.iter().map(appearance_from_row).collect();
    let aids: Vec<i32> = apps.iter().filter_map(|a| a.id).collect();
    if !aids.is_empty() {
        let prop_rows = c
            .query(
                "SELECT appearance_id, property, value FROM layerappearances_properties WHERE appearance_id = ANY($1) ORDER BY property",
                &[&aids],
            )
            .await?;
        for a in apps.iter_mut() {
            let aid = a.id.unwrap_or(-1);
            a.properties = prop_rows
                .iter()
                .filter(|r| r.get::<_, i32>("appearance_id") == aid)
                .map(|r| {
                    let key: String = r.get("property");
                    let val: Option<String> = r.get("value");
                    (key.clone(), match val {
                        Some(s) => PropValue::from_db_string(&s),
                        None => PropValue::Str("null".to_string()),
                    })
                })
                .collect();
        }
    }
    Ok(apps)
}

pub async fn load_appearances_restricted(
    c: &tokio_postgres::Client,
    fields: &[String],
    where_sql: &str,
    params: &[&(dyn ToSql + Sync)],
) -> Result<Vec<LayerAppearance>, String> {
    let mut sel = Vec::new();
    for f in fields {
        let col = field_column(ResourceType::Appearances, f).ok_or("bad field")?;
        sel.push(format!("{} AS {}", col, pg_alias(f)));
    }
    let sql = format!(
        "SELECT {} FROM layerappearances {} ORDER BY layerappearances.id",
        sel.join(", "),
        where_sql
    );
    let rows = c.query(&sql, params).await.map_err(|e| e.to_string())?;
    let mut out = Vec::new();
    for row in &rows {
        let mut a = LayerAppearance::new_fresh();
        a.restricted = Some(fields.to_vec());
        a.properties_raw = None; // loaded-style: properties serialize as {}
        for f in fields {
            let al = pg_alias(f);
            match f.as_str() {
                "id" => a.id = row.get::<_, Option<i32>>(&al[..]),
                "attribution" => a.attribution = row.get(&al[..]),
                "hoverable" => a.hoverable = row.get(&al[..]),
                "clickable" => a.clickable = row.get(&al[..]),
                "hoverTemplate" => a.hover_template = row.get(&al[..]),
                "name" => a.name = row.get(&al[..]),
                "maxResolution" => a.max_resolution = row.get(&al[..]),
                "minResolution" => a.min_resolution = row.get(&al[..]),
                "opacity" => a.opacity = row.get(&al[..]),
                "visible" => a.visible = row.get(&al[..]),
                _ => {}
            }
        }
        out.push(a);
    }
    Ok(out)
}

