async fn datasources_from_rows(
    c: &tokio_postgres::Client,
    rows: &[Row],
) -> Result<Vec<DataSource>, String> {
    let mut dss: Vec<DataSource> = Vec::new();
    let mut tilegrid_ids: Vec<i32> = Vec::new();
    let mut xyz_extent_ids: Vec<i32> = Vec::new();
    let mut wmts_ids: Vec<i32> = Vec::new();
    let mut xyz_ids: Vec<i32> = Vec::new();
    for row in rows {
        let mut ds = datasource_from_row(row);
        datasource_fix_wfs_version(&mut ds, row);
        match ds.kind {
            DsKind::TileWms => {
                if let Some(gid) = row.get::<_, Option<i32>>("tw_tilegrid_id") {
                    tilegrid_ids.push(gid);
                    ds.tile_grid = Some(Box::new(TileGrid::from_db(false)));
                    ds.tile_grid.as_mut().unwrap().id = Some(gid);
                }
            }
            DsKind::Wmts => {
                wmts_ids.push(ds.id.unwrap_or(-1));
                if let Some(gid) = row.get::<_, Option<i32>>("wmts_tilegrid_id") {
                    tilegrid_ids.push(gid);
                    ds.tile_grid = Some(Box::new(TileGrid::from_db(true)));
                    ds.tile_grid.as_mut().unwrap().id = Some(gid);
                }
            }
            DsKind::Xyz => {
                xyz_ids.push(ds.id.unwrap_or(-1));
                if let Some(eid) = row.get::<_, Option<i32>>("xyz_extent_id") {
                    xyz_extent_ids.push(eid);
                }
            }
            _ => {}
        }
        dss.push(ds);
    }
    // tile grids (full)
    let grids = load_tilegrids(c, &tilegrid_ids).await?;
    // wmts urls
    let url_rows = if wmts_ids.is_empty() {
        Vec::new()
    } else {
        c.query(
            "SELECT wmtslayerdatasources_id, urls FROM wmtslayerdatasources_urls WHERE wmtslayerdatasources_id = ANY($1)",
            &[&wmts_ids],
        )
        .await
        .map_err(|e| e.to_string())?
    };
    // xyz extents + resolutions
    let xyz_extents = load_extents(c, &xyz_extent_ids).await?;
    let res_rows = if xyz_ids.is_empty() {
        Vec::new()
    } else {
        c.query(
            "SELECT xyzlayerdatasrc_id, resolution, idx FROM xyzlayerdatasrc_resolution WHERE xyzlayerdatasrc_id = ANY($1) ORDER BY idx",
            &[&xyz_ids],
        )
        .await
        .map_err(|e| e.to_string())?
    };
    for ds in dss.iter_mut() {
        let id = ds.id.unwrap_or(-1);
        match ds.kind {
            DsKind::TileWms | DsKind::Wmts => {
                let gid = ds.tile_grid.as_ref().and_then(|g| g.id);
                if let Some(gid) = gid {
                    if let Some(g) = grids.iter().find(|g| g.id == Some(gid)) {
                        ds.tile_grid = Some(Box::new(g.clone()));
                    }
                }
                if ds.kind == DsKind::Wmts {
                    ds.urls = Some(
                        url_rows
                            .iter()
                            .filter(|r| r.get::<_, i32>("wmtslayerdatasources_id") == id)
                            .map(|r| r.get::<_, Option<String>>("urls"))
                            .collect(),
                    );
                }
            }
            DsKind::Xyz => {
                if let Some(row) = rows.iter().find(|r| r.get::<_, i32>("id") == id) {
                    if let Some(eid) = row.get::<_, Option<i32>>("xyz_extent_id") {
                        ds.extent = xyz_extents.iter().find(|e| e.id == Some(eid)).cloned().map(Box::new);
                    }
                }
                let mut list = Vec::new();
                for r in res_rows.iter().filter(|r| r.get::<_, i32>("xyzlayerdatasrc_id") == id) {
                    let blob: Option<Vec<u8>> = r.get("resolution");
                    if let Some(b) = blob {
                        if let Some((x, y)) = javadoc::deserialize_point2d_double(&b) {
                            list.push(Point { x, y });
                        }
                    }
                }
                ds.resolutions = Some(list);
            }
            _ => {}
        }
    }
    Ok(dss)
}

pub async fn load_tilegrids(
    c: &tokio_postgres::Client,
    ids: &[i32],
) -> Result<Vec<TileGrid>, String> {
    if ids.is_empty() {
        return Ok(Vec::new());
    }
    let rows = c
        .query(
            "SELECT g.id, g.created, g.modified, g.type, g.tilegridorigin_x, g.tilegridorigin_y, \
             g.tilesize, g.tilegridextent_id, (w.id IS NOT NULL) AS is_wmts \
             FROM tilegrids g LEFT JOIN wmtstilegrids w ON w.id = g.id WHERE g.id = ANY($1) ORDER BY g.id",
            &[&ids],
        )
        .await
        .map_err(|e| e.to_string())?;
    let mut grids: Vec<TileGrid> = rows
        .iter()
        .map(|r| {
            let is_wmts: bool = r.get("is_wmts");
            tilegrid_from_row(r, is_wmts)
        })
        .collect();
    // resolutions
    let res_rows = c
        .query(
            "SELECT tilegrid_id, resolution, idx FROM tilegrid_resolution WHERE tilegrid_id = ANY($1) ORDER BY idx",
            &[&ids],
        )
        .await
        .map_err(|e| e.to_string())?;
    // matrix ids
    let wids: Vec<i32> = grids.iter().filter(|g| g.is_wmts).filter_map(|g| g.id).collect();
    let mat_rows = if wids.is_empty() {
        Vec::new()
    } else {
        c.query(
            "SELECT wmtstilegrids_id, matrixids FROM wmtstilegrids_matrixids WHERE wmtstilegrids_id = ANY($1)",
            &[&wids],
        )
        .await
        .map_err(|e| e.to_string())?
    };
    // extents
    let ext_ids: Vec<i32> = rows.iter().filter_map(|r| r.get::<_, Option<i32>>("tilegridextent_id")).collect();
    let extents = load_extents(c, &ext_ids).await?;
    for (g, r) in grids.iter_mut().zip(rows.iter()) {
        let gid = g.id.unwrap_or(-1);
        g.resolutions = Some(
            res_rows
                .iter()
                .filter(|rr| rr.get::<_, i32>("tilegrid_id") == gid)
                .map(|rr| rr.get::<_, Option<f64>>("resolution").unwrap_or(0.0))
                .collect(),
        );
        if g.is_wmts {
            g.matrix_ids = Some(
                mat_rows
                    .iter()
                    .filter(|rr| rr.get::<_, i32>("wmtstilegrids_id") == gid)
                    .map(|rr| rr.get::<_, Option<String>>("matrixids"))
                    .collect(),
            );
        }
        if let Some(eid) = r.get::<_, Option<i32>>("tilegridextent_id") {
            g.extent = extents.iter().find(|e| e.id == Some(eid)).cloned().map(Box::new);
        }
    }
    Ok(grids)
}

pub async fn load_extents(
    c: &tokio_postgres::Client,
