pub async fn load_role_names(
    c: &tokio_postgres::Client,
    user_id: i32,
) -> Result<Vec<String>, tokio_postgres::Error> {
    let rows = c
        .query(
            "SELECT r.name FROM users_roles ur JOIN roles r ON r.id = ur.role_id WHERE ur.user_id = $1
             UNION
             SELECT r.name FROM usergroups_roles gr
               JOIN user_usergroup ug ON ug.usergroup_id = gr.usergroup_id
               JOIN roles r ON r.id = gr.role_id
             WHERE ug.user_id = $1",
            &[&user_id],
        )
