        .query("SELECT usergroup_id FROM user_usergroup WHERE user_id = $1", &[&user_id])
        .await?;
    Ok(rows.iter().map(|r| r.get("usergroup_id")).collect())
}

pub async fn load_principal_perms(
    c: &tokio_postgres::Client,
    user_id: i32,
    member_of: &[i32],
) -> Result<PrincipalPerms, tokio_postgres::Error> {
    let mut perms = PrincipalPerms { user_perms: Default::default(), group_perms: Default::default(), member_of: member_of.to_vec() };
    let rows = c
        .query(
            "SELECT up.entity_id AS entity_id, pcp.permissions AS permissions
             FROM userpermissions up
             JOIN permissioncollections_permissions pcp ON pcp.permissioncollections_id = up.userpermissions_id
             WHERE up.userpermissions_key = $1",
            &[&user_id],
        )
        .await?;
    for r in &rows {
        let eid: i32 = r.get("entity_id");
        let p: Option<String> = r.get("permissions");
        if let Some(p) = p {
            if let Some(perm) = Permission::from_string(&p) {
                perms.user_perms.entry(eid).or_default().push(perm);
            }
        }
    }
    if !member_of.is_empty() {
        let rows = c
            .query(
                "SELECT gp.entity_id AS entity_id, pcp.permissions AS permissions
                 FROM grouppermissions gp
                 JOIN permissioncollections_permissions pcp ON pcp.permissioncollections_id = gp.grouppermissions_id
                 WHERE gp.grouppermissions_key = ANY($1)",
                &[&member_of],
            )
            .await?;
        for r in &rows {
            let eid: i32 = r.get("entity_id");
            let p: Option<String> = r.get("permissions");
            if let Some(p) = p {
                if let Some(perm) = Permission::from_string(&p) {
                    perms.group_perms.entry(eid).or_default().push(perm);
                }
            }
        }
    }
    Ok(perms)
}

