impl ResourceType {
    pub fn from_path(p: &str) -> Option<ResourceType> {
        match p {
            "users" => Some(ResourceType::Users),
            "groups" => Some(ResourceType::Groups),
            "roles" => Some(ResourceType::Roles),
            "layers" => Some(ResourceType::Layers),
            "layerdatasources" => Some(ResourceType::DataSources),
            "layerappearances" => Some(ResourceType::Appearances),
            _ => None,
        }
    }
    /// The permission-evaluator "kind" used for access decisions.
    pub fn always_allow_read(&self) -> bool {
        matches!(self, ResourceType::Roles | ResourceType::DataSources | ResourceType::Appearances)
    }
}

/// The set of private, non-static, primitive/wrapper/String fields for each
/// entity class (EntityUtil.getFilterableOrRestrictableFieldNames), used for
/// `output:only` and /filter.
pub fn filterable_fields(rt: ResourceType) -> Vec<&'static str> {
    match rt {
        ResourceType::Users => vec![
            "accountName", "password", "active", "firstName", "lastName", "email", "id",
        ],
        ResourceType::Groups => vec!["name", "id"],
        ResourceType::Roles => vec!["name", "description", "id"],
        ResourceType::Layers => vec!["name", "description", "id"],
        ResourceType::DataSources => vec!["name", "type", "url", "format", "id"],
        ResourceType::Appearances => vec![
            "attribution", "hoverable", "clickable", "hoverTemplate", "name", "maxResolution",
            "minResolution", "opacity", "visible", "id",
        ],
    }
}

/// Field -> java type for filter value casting.
#[derive(Clone, Copy, PartialEq)]
pub enum FieldType {
    Str,
    Int,
    BoolPrim,
    BoolWrap,
    Double,
}

pub fn field_type(rt: ResourceType, field: &str) -> Option<FieldType> {
    match rt {
        ResourceType::Users => match field {
            "id" => Some(FieldType::Int),
            "active" => Some(FieldType::BoolPrim),
            "accountName" | "password" | "firstName" | "lastName" | "email" => {
                Some(FieldType::Str)
            }
            _ => None,
        },
        ResourceType::Groups => match field {
            "id" => Some(FieldType::Int),
            "name" => Some(FieldType::Str),
            _ => None,
        },
        ResourceType::Roles => match field {
            "id" => Some(FieldType::Int),
            "name" | "description" => Some(FieldType::Str),
            _ => None,
        },
        ResourceType::Layers => match field {
            "id" => Some(FieldType::Int),
            "name" | "description" => Some(FieldType::Str),
            _ => None,
        },
        ResourceType::DataSources => match field {
            "id" => Some(FieldType::Int),
            "name" | "type" | "url" | "format" => Some(FieldType::Str),
            _ => None,
        },
        ResourceType::Appearances => match field {
            "id" => Some(FieldType::Int),
            "attribution" | "hoverTemplate" | "name" => Some(FieldType::Str),
            "hoverable" | "clickable" | "visible" => Some(FieldType::BoolWrap),
            "maxResolution" | "minResolution" | "opacity" => Some(FieldType::Double),
            _ => None,
        },
    }
}

/// DB column for a filterable/restrictable field.
pub fn field_column(rt: ResourceType, field: &str) -> Option<&'static str> {
    match rt {
        ResourceType::Users => match field {
            "id" => Some("p.id"),
            "firstName" => Some("p.firstname"),
            "lastName" => Some("p.lastname"),
            "email" => Some("p.email"),
            "accountName" => Some("u.accountname"),
            "password" => Some("u.password"),
            "active" => Some("u.active"),
            _ => None,
        },
        ResourceType::Groups => match field {
            "id" => Some("usergroups.id"),
            "name" => Some("usergroups.name"),
            _ => None,
        },
        ResourceType::Roles => match field {
            "id" => Some("roles.id"),
            "name" => Some("roles.name"),
            "description" => Some("roles.description"),
            _ => None,
        },
        ResourceType::Layers => match field {
            "id" => Some("layers.id"),
            "name" => Some("layers.name"),
            "description" => Some("layers.description"),
            _ => None,
        },
        ResourceType::DataSources => match field {
            "id" => Some("d.id"),
            "name" => Some("d.name"),
            "type" => Some("d.type"),
            "url" => Some("d.url"),
            "format" => Some("d.format"),
            _ => None,
        },
        ResourceType::Appearances => match field {
            "id" => Some("layerappearances.id"),
            "attribution" => Some("layerappearances.attribution"),
            "hoverable" => Some("layerappearances.hoverable"),
            "clickable" => Some("layerappearances.clickable"),
            "hoverTemplate" => Some("layerappearances.hovertemplate"),
            "name" => Some("layerappearances.name"),
            "maxResolution" => Some("layerappearances.maxresolution"),
            "minResolution" => Some("layerappearances.minresolution"),
            "opacity" => Some("layerappearances.opacity"),
            "visible" => Some("layerappearances.visible"),
            _ => None,
        },
    }
}

// ---------------------------------------------------------------------------
// Row -> entity helpers
// ---------------------------------------------------------------------------

fn get_opt<T: tokio_postgres::types::FromSql + 'static>(row: &Row, col: &str) -> Option<T> {
    row.try_get(col)
}

pub fn point_from(x: Option<f64>, y: Option<f64>) -> Option<Point> {
    match (x, y) {
        (None, None) => None,
        (x, y) => Some(Point { x: x.unwrap_or(0.0), y: y.unwrap_or(0.0) }),
    }
}

pub fn role_from_row(row: &Row) -> Role {
    Role {
        id: row.get("id"),
        created: get_opt(row, "created"),
        modified: get_opt(row, "modified"),
        name: row.get("name"),
        description: get_opt(row, "description"),
        fresh: false,
    }
}

pub fn user_from_joined_row(row: &Row) -> User {
    User {
        id: row.get("u_id"),
        created: row.try_get("u_created").unwrap_or(None),
        modified: row.try_get("u_modified").unwrap_or(None),
        first_name: row.try_get("u_firstname").unwrap_or(None),
        last_name: row.try_get("u_lastname").unwrap_or(None),
        email: row.try_get("u_email").unwrap_or(None),
        birthday: row.try_get("u_birthday").unwrap_or(None),
        language: row.try_get("u_language").unwrap_or(None),
        account_name: row.try_get("u_accountname").unwrap_or(None),
        password: row.try_get("u_password").unwrap_or(None),
        active: row.try_get::<_, Option<bool>>("u_active").unwrap_or(None).unwrap_or(false),
        roles: Some(Vec::new()),
        user_group_ids: Some(Vec::new()),
        fresh: false,
        restricted: None,
    }
}

pub fn group_from_row(row: &Row) -> UserGroup {
    UserGroup {
        id: row.get("id"),
        created: get_opt(row, "created"),
        modified: get_opt(row, "modified"),
        name: get_opt(row, "name"),
        owner: None,
        members: Some(Vec::new()),
        roles: Some(Vec::new()),
        fresh: false,
        restricted: None,
    }
}

pub fn extent_from_row(row: &Row) -> Extent {
    Extent {
        id: row.get("id"),
        created: get_opt(row, "created"),
        modified: get_opt(row, "modified"),
        lower_left: point_from(get_opt(row, "lowerleft_x"), get_opt(row, "lowerleft_y")),
        upper_right: point_from(get_opt(row, "upperright_x"), get_opt(row, "upperright_y")),
        fresh: false,
    }
}

pub fn appearance_from_row(row: &Row) -> LayerAppearance {
    LayerAppearance {
        id: row.get("id"),
        created: get_opt(row, "created"),
        modified: get_opt(row, "modified"),
        attribution: get_opt(row, "attribution"),
        hoverable: get_opt(row, "hoverable"),
        clickable: get_opt(row, "clickable"),
        hover_template: get_opt(row, "hovertemplate"),
        properties: PropState::Loaded(Vec::new()),
        name: get_opt(row, "name"),
        max_resolution: get_opt(row, "maxresolution"),
        min_resolution: get_opt(row, "minresolution"),
        opacity: get_opt(row, "opacity"),
        visible: get_opt(row, "visible"),
        fresh: false,
        restricted: None,
    }
}

pub fn layer_from_row(row: &Row) -> Layer {
    Layer {
        id: row.get("id"),
        created: get_opt(row, "created"),
        modified: get_opt(row, "modified"),
        name: get_opt(row, "name"),
        description: get_opt(row, "description"),
        source: None,
        appearance: None,
        fresh: false,
        restricted: None,
    }
}

pub fn tilegrid_from_row(row: &Row, is_wmts: bool) -> TileGrid {
    TileGrid {
        id: row.get("id"),
        created: get_opt(row, "created"),
        modified: get_opt(row, "modified"),
        grid_type: get_opt(row, "type"),
        origin: point_from(get_opt(row, "tilegridorigin_x"), get_opt(row, "tilegridorigin_y")),
        extent: None,
        tile_size: get_opt(row, "tilesize"),
        resolutions: Some(Vec::new()),
        is_wmts,
        matrix_ids: if is_wmts { Some(Vec::new()) } else { None },
        fresh: false,
    }
}

pub fn datasource_from_row(row: &Row) -> DataSource {
    let is_img: bool = row.get("is_img");
    let is_tile: bool = row.get("is_tile");
    let is_wfs: bool = row.get("is_wfs");
    let is_wmts: bool = row.get("is_wmts");
    let is_xyz: bool = row.get("is_xyz");
    let kind = if is_tile {
        DsKind::TileWms
    } else if is_img {
        DsKind::ImageWms
    } else if is_wfs {
        DsKind::Wfs
    } else if is_wmts {
        DsKind::Wmts
    } else if is_xyz {
        DsKind::Xyz
    } else {
        DsKind::Base
    };
    let mut ds = DataSource::new_loaded(kind);
    ds.id = row.get("id");
    ds.created = get_opt(row, "created");
    ds.modified = get_opt(row, "modified");
    ds.name = get_opt(row, "name");
    ds.ds_type = get_opt(row, "type");
    ds.url = get_opt(row, "url");
    ds.format = get_opt(row, "format");
    match kind {
        DsKind::ImageWms | DsKind::TileWms => {
            ds.width = row.get::<_, Option<i32>>("width").unwrap_or(0);
            ds.height = row.get::<_, Option<i32>>("height").unwrap_or(0);
            ds.version = get_opt(row, "version");
            ds.layer_names = get_opt(row, "layernames");
            ds.layer_styles = get_opt(row, "layerstyles");
            ds.requestable_by_path = get_opt(row, "requestablebypath");
            ds.custom_request_path = get_opt(row, "customrequestpath");
            if kind == DsKind::TileWms {
                ds.request_with_tiled = get_opt(row, "request_with_tiled");
            }
        }
        DsKind::Wfs => {
            ds.version = get_opt(row, "wfs_version");
            ds.type_name = get_opt(row, "typename");
            ds.type_names = get_opt(row, "typenames");
        }
        DsKind::Wmts => {
            ds.capabilities_url = get_opt(row, "capabilitiesurl");
            ds.matrix_set = get_opt(row, "matrixset");
            ds.projection = get_opt(row, "projection");
            ds.request_encoding = get_opt(row, "requestencoding");
            ds.wmts_layer = get_opt(row, "wmtslayer");
            ds.wmts_style = get_opt(row, "wmtsstyle");
        }
        DsKind::Xyz => {
            ds.center = point_from(get_opt(row, "center_x"), get_opt(row, "center_y"));
            ds.tile_size = get_opt(row, "xyz_tilesize");
        }
        DsKind::Base => {}
    }
    ds
}

/// Column list for loading data sources (with subtype left joins).
pub const DS_SELECT: &str = "SELECT d.id, d.created, d.modified, d.name, d.type, d.url, d.format, \
     (i.id IS NOT NULL) AS is_img, (t.id IS NOT NULL) AS is_tile, (w.id IS NOT NULL) AS is_wfs, \
     (m.id IS NOT NULL) AS is_wmts, (x.id IS NOT NULL) AS is_xyz, \
     i.width, i.height, i.version, i.layernames, i.layerstyles, i.requestablebypath, i.customrequestpath, \
     t.tilegrid_id AS tw_tilegrid_id, t.request_with_tiled, \
     w.version AS wfs_version, w.typename, w.typenames, \
     m.tilegrid_id AS wmts_tilegrid_id, m.capabilitiesurl, m.matrixset, m.projection, m.requestencoding, m.wmtslayer, m.wmtsstyle, \
     x.center_x, x.center_y, x.tilesize AS xyz_tilesize, x.extent_id AS xyz_extent_id \
     FROM layerdatasources d \
     LEFT JOIN imagewmslayerdatasources i ON i.id = d.id \
     LEFT JOIN tilewmslayerdatasources t ON t.id = d.id \
     LEFT JOIN wfslayerdatasources w ON w.id = d.id \
     LEFT JOIN wmtslayerdatasources m ON m.id = d.id \
     LEFT JOIN xyzlayerdatasources x ON x.id = d.id";

/// Permission data of the principal user, loaded once per request.
#[derive(Clone, Default)]
pub struct PrincipalPerms {
    /// entity_id -> permissions granted directly to the principal user
    pub user_perms: HashMap<i32, Vec<Permission>>,
    /// entity_id -> permissions granted via the principal's groups
    pub group_perms: HashMap<i32, Vec<Permission>>,
    /// group ids the principal is a member of
    pub member_of: Vec<i32>,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_permission_from_string() {
        assert_eq!(Permission::from_string("read"), Some(Permission::Read));
        assert_eq!(Permission::from_string("ADMIN"), Some(Permission::Admin));
        assert_eq!(Permission::from_string("bogus"), None);
    }

    #[test]
    fn test_prop_value_from_db() {
        assert_eq!(PropValue::from_db_string("true"), PropValue::Bool(true));
        assert_eq!(PropValue::from_db_string("FALSE"), PropValue::Bool(false));
        assert_eq!(PropValue::from_db_string("42"), PropValue::Long(42));
        assert_eq!(PropValue::from_db_string("-7"), PropValue::Long(-7));
        assert_eq!(PropValue::from_db_string("3.5"), PropValue::Double(3.5));
        assert_eq!(PropValue::from_db_string("1e5"), PropValue::Double(100000.0));
        assert_eq!(PropValue::from_db_string("foo"), PropValue::Str("foo".into()));
    }

    #[test]
    fn test_java_equals_ignores_id() {
        let mut a = User::new_fresh();
        a.id = Some(3);
        let mut b = User::new_fresh();
        b.id = Some(45);
        assert!(a.java_equals(&b));
        b.account_name = Some("x".into());
        assert!(!a.java_equals(&b));
    }

    #[test]
    fn test_filterable_fields() {
        assert!(filterable_fields(ResourceType::Users).contains(&"accountName"));
        assert!(!filterable_fields(ResourceType::Users).contains(&"birthday"));
        assert!(!filterable_fields(ResourceType::Users).contains(&"roles"));
    }
}

