{"content": "//! Entity model mirroring the SHOGun-Core JPA entities of the slice, plus
//! database load/save logic that mirrors what Hibernate does.

use chrono::{NaiveDate, NaiveDateTime};
use serde_json::Value;
use std::collections::HashMap;
use tokio_postgres::Row;

use crate::javadoc;

#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub enum Permission {
    Admin,
    Create,
    Delete,
    Update,
    Read,
}

impl Permission {
    /// Mimics Permission.fromString (case-insensitive, null on unknown).
    pub fn from_string(s: &str) -> Option<Permission> {
        match s.to_uppercase().as_str() {
            "ADMIN" => Some(Permission::Admin),
            "CREATE" => Some(Permission::Create),
            "DELETE" => Some(Permission::Delete),
            "UPDATE" => Some(Permission::Update),
            "READ" => Some(Permission::Read),
            _ => None,
        }
    }
    #[allow(dead_code)]
    pub fn as_str(&self) -> &'static str {
        match self {
            Permission::Admin => "ADMIN",
            Permission::Create => "CREATE",
            Permission::Delete => "DELETE",
            Permission::Update => "UPDATE",
            Permission::Read => "READ",
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum DsKind {
    Base,
    ImageWms,
    TileWms,
    Wfs,
    Wmts,
    Xyz,
}

#[derive(Clone, Copy, PartialEq, Debug)]
pub struct Point {
    pub x: f64,
    pub y: f64,
}

/// A value of `LayerAppearance.properties`.
#[derive(Clone, PartialEq, Debug)]
pub enum PropValue {
    Str(String),
    Long(i64),
    Double(f64),
    Bool(bool),
}

impl PropValue {
    /// Mimics PropertyValueConverter.convertToEntityAttribute.
    pub fn from_db_string(s: &str) -> PropValue {
        let lower = s.to_lowercase();
        if lower == "true" {
            return PropValue::Bool(true);
        }
        if lower == "false" {
            return PropValue::Bool(false);
        }
        if javadoc::number_utils_is_parsable(s) {
            if javadoc::number_utils_is_digits(s)
                || (s.starts_with('-') && javadoc::number_utils_is_digits(&s[1..]))
            {
                if let Ok(v) = s.parse::<i64>() {
                    return PropValue::Long(v);
                }
            }
            if let Ok(v) = s.parse::<f64>() {
                return PropValue::Double(v);
            }
        }
        PropValue::Str(s.to_string())
    }
}

/// State of the `LayerAppearance.properties` map.
#[derive(Clone, Debug)]
pub enum PropState {
    /// loaded from the database (converted values)
    Loaded(Vec<(String, PropValue)>),
    /// set from a request body (raw Jackson values)
    Raw(Vec<(String, Value)>),
    /// explicitly set to null
    Null,
}

#[derive(Clone, Debug)]
pub struct Role {
    pub id: Option<i32>,
    pub created: Option<NaiveDateTime>,
    pub modified: Option<NaiveDateTime>,
    pub name: Option<String>,
    pub description: Option<String>,
    /// true when this instance was constructed from JSON or by a restricted
    /// projection, i.e. its `created` timestamp is "now" for equals purposes.
    pub fresh: bool,
}

impl Role {
    pub fn new_fresh() -> Role {
        Role { id: None, created: None, modified: None, name: None, description: None, fresh: true }
    }
    /// Mimics Role.equals (class + created + name + description). id is NOT
    /// part of equals.
    pub fn java_equals(&self, other: &Role) -> bool {
        self.fresh == other.fresh && self.name == other.name && self.description == other.description
    }
}

#[derive(Clone, Debug)]
pub struct User {
    pub id: Option<i32>,
    pub created: Option<NaiveDateTime>,
    pub modified: Option<NaiveDateTime>,
    pub first_name: Option<String>,
    pub last_name: Option<String>,
    pub email: Option<String>,
    pub birthday: Option<NaiveDate>,
    pub language: Option<String>,
    pub account_name: Option<String>,
    pub password: Option<String>,
    pub active: bool,
    pub roles: Option<Vec<Role>>,
    /// Serialized as ids only (@JsonIdentityReference alwaysAsId).
    pub user_group_ids: Option<Vec<i32>>,
    pub fresh: bool,
    /// Some(fields) => created by a restricted (output:only) projection.
    pub restricted: Option<Vec<String>>,
}

impl User {
    pub fn new_fresh() -> User {
        User {
            id: None,
            created: None,
            modified: None,
            first_name: None,
            last_name: None,
            email: None,
            birthday: None,
            language: None,
            account_name: None,
            password: None,
            active: false,
            roles: Some(Vec::new()),
            user_group_ids: Some(Vec::new()),
            fresh: true,
            restricted: None,
        }
    }
    /// Mimics User.equals (class + created + person fields + accountName +
    /// password + active). id is NOT part of equals.
    pub fn java_equals(&self, other: &User) -> bool {
        self.fresh == other.fresh
            && self.first_name == other.first_name
            && self.last_name == other.last_name
            && self.email == other.email
            && self.birthday == other.birthday
            && self.language == other.language
            && self.account_name == other.account_name
            && self.password == other.password
            && self.active == other.active
    }
}

