impl TileGrid {
    /// Mimics `new TileGrid()`: tileSize defaults to 256, resolutions null.
    pub fn new_fresh(is_wmts: bool) -> TileGrid {
        TileGrid {
            id: None,
            created: None,
            modified: None,
            grid_type: None,
            origin: None,
            extent: None,
            tile_size: Some(256),
            resolutions: None,
            is_wmts,
