        }
    }
    pub fn from_db(is_wmts: bool) -> TileGrid {
        TileGrid {
            id: None,
            created: None,
            modified: None,
            grid_type: None,
            origin: None,
            extent: None,
            tile_size: None,
            resolutions: None,
            is_wmts,
            matrix_ids: None,
            fresh: false,
        }
    }
}

#[derive(Clone, Debug)]
pub struct DataSource {
    pub kind: DsKind,
    pub id: Option<i32>,
    pub created: Option<NaiveDateTime>,
    pub modified: Option<NaiveDateTime>,
    pub name: Option<String>,
    pub ds_type: Option<String>,
    pub url: Option<String>,
    pub format: Option<String>,
    // ImageWms / TileWms
    pub width: i32,
    pub height: i32,
    pub version: Option<String>,
    pub layer_names: Option<String>,
    pub layer_styles: Option<String>,
    pub requestable_by_path: Option<bool>,
    pub custom_request_path: Option<String>,
    // TileWms
    pub tile_grid: Option<Box<TileGrid>>,
    pub request_with_tiled: Option<bool>,
    // Wfs
    pub type_name: Option<String>,
    pub type_names: Option<String>,
    // Wmts
    pub urls: Option<Vec<Option<String>>>,
    pub wmts_layer: Option<String>,
    pub wmts_style: Option<String>,
    pub projection: Option<String>,
    pub matrix_set: Option<String>,
    pub request_encoding: Option<String>,
    pub capabilities_url: Option<String>,
    // Xyz
    pub center: Option<Point>,
    pub extent: Option<Box<Extent>>,
    pub resolutions: Option<Vec<Option<Point>>>,
    pub tile_size: Option<i32>,
    pub fresh: bool,
}

