            _ => None,
        }
    }
    /// The permission-evaluator "kind" used for access decisions.
    pub fn always_allow_read(&self) -> bool {
        matches!(self, ResourceType::Roles | ResourceType::DataSources | ResourceType::Appearances)
    }
}

/// The set of private, non-static, primitive/wrapper/String fields for each
/// entity class (EntityUtil.getFilterableOrRestrictableFieldNames), used for
/// `output:only` and /filter.
pub fn filterable_fields(rt: ResourceType) -> Vec<&'static str> {
    match rt {
        ResourceType::Users => vec![
            "accountName", "password", "active", "firstName", "lastName", "email", "id",
        ],
        ResourceType::Groups => vec!["name", "id"],
        ResourceType::Roles => vec!["name", "description", "id"],
        ResourceType::Layers => vec!["name", "description", "id"],
        ResourceType::DataSources => vec!["name", "type", "url", "format", "id"],
        ResourceType::Appearances => vec![
            "attribution", "hoverable", "clickable", "hoverTemplate", "name", "maxResolution",
            "minResolution", "opacity", "visible", "id",
        ],
    }
}

/// Field -> java type for filter value casting.
#[derive(Clone, Copy, PartialEq)]
pub enum FieldType {
    Str,
    Int,
    BoolPrim,
    BoolWrap,
    Double,
}

pub fn field_type(rt: ResourceType, field: &str) -> Option<FieldType> {
    match rt {
        ResourceType::Users => match field {
            "id" => Some(FieldType::Int),
            "active" => Some(FieldType::BoolPrim),
            "accountName" | "password" | "firstName" | "lastName" | "email" => {
                Some(FieldType::Str)
            }
            _ => None,
        },
        ResourceType::Groups => match field {
            "id" => Some(FieldType::Int),
            "name" => Some(FieldType::Str),
            _ => None,
        },
        ResourceType::Roles => match field {
            "id" => Some(FieldType::Int),
            "name" | "description" => Some(FieldType::Str),
            _ => None,
        },
        ResourceType::Layers => match field {
            "id" => Some(FieldType::Int),
            "name" | "description" => Some(FieldType::Str),
            _ => None,
        },
        ResourceType::DataSources => match field {
            "id" => Some(FieldType::Int),
            "name" | "type" | "url" | "format" => Some(FieldType::Str),
            _ => None,
        },
        ResourceType::Appearances => match field {
            "id" => Some(FieldType::Int),
            "attribution" | "hoverTemplate" | "name" => Some(FieldType::Str),
            "hoverable" | "clickable" | "visible" => Some(FieldType::BoolWrap),
            "maxResolution" | "minResolution" | "opacity" => Some(FieldType::Double),
            _ => None,
        },
    }
}

/// DB column for a filterable/restrictable field.
pub fn field_column(rt: ResourceType, field: &str) -> Option<&'static str> {
    match rt {
        ResourceType::Users => match field {
