{"content": "//! JSON serialization and deserialization mimicking Jackson's behaviour for
//! the SHOGun-Core entity classes (property sets, coercion, errors, the
//! `userGroups` id-reference resolution and Java `equals` deduplication of
//! deserialized HashSets).

use serde_json::{Map, Value};

use crate::javadoc::*;
use crate::model::*;

/// All errors raised while reading a request body are "checked" exceptions in
/// Java (IOException family): fields applied before the error still get
/// committed for PUT.
#[derive(Debug)]
pub struct JacksonError;

pub type JResult<T> = Result<T, JacksonError>;

const IGNORABLE: &[&str] = &["created", "modified", "userPermissions", "groupPermissions"];

// ---------------------------------------------------------------------------
// Serialization
// ---------------------------------------------------------------------------

fn w_null(out: &mut String) {
    out.push_str("null");
}

fn w_str(out: &mut String, s: &str) {
    write_json_string(out, s);
}

fn w_opt_str(out: &mut String, key: &str, v: &Option<String>, first: &mut bool) {
    if !*first {
        out.push(',');
    }
    *first = false;
    out.push('"');
    out.push_str(key);
    out.push_str("\":");
    match v {
        Some(s) => w_str(out, s),
        None => w_null(out),
    }
}

fn w_raw(out: &mut String, key: &str, v: &str, first: &mut bool) {
    if !*first {
        out.push(',');
    }
    *first = false;
    out.push('"');
    out.push_str(key);
    out.push_str("\":");
    out.push_str(v);
}

fn w_opt_i32(out: &mut String, key: &str, v: Option<i32>, first: &mut bool) {
    match v {
        Some(n) => w_raw(out, key, &n.to_string(), first),
        None => w_raw(out, key, "null", first),
    }
}

fn w_i32(out: &mut String, key: &str, v: i32, first: &mut bool) {
    w_raw(out, key, &v.to_string(), first);
}

fn w_opt_f64(out: &mut String, key: &str, v: Option<f64>, first: &mut bool) {
    match v {
        Some(n) => w_raw(out, key, &java_double_to_string(n), first),
        None => w_raw(out, key, "null", first),
    }
}

fn w_opt_bool(out: &mut String, key: &str, v: Option<bool>, first: &mut bool) {
    match v {
        Some(b) => w_raw(out, key, if b { "true" } else { "false" }, first),
        None => w_raw(out, key, "null", first),
    }
}

fn w_bool(out: &mut String, key: &str, v: bool, first: &mut bool) {
    w_raw(out, key, if v { "true" } else { "false" }, first);
}

fn w_key(out: &mut String, key: &str, first: &mut bool) {
    if !*first {
        out.push(',');
    }
    *first = false;
    out.push('"');
    out.push_str(key);
    out.push_str("\":");
}

fn w_point(out: &mut String, p: &Point) {
    out.push('{');
    let mut first = true;
    w_raw(out, "x", &java_double_to_string(p.x), &mut first);
    w_raw(out, "y", &java_double_to_string(p.y), &mut first);
    out.push('}');
}

fn w_opt_point(out: &mut String, key: &str, v: &Option<Point>, first: &mut bool) {
    w_key(out, key, first);
    match v {
        Some(p) => w_point(out, p),
        None => w_null(out),
    }
}

fn w_date(out: &mut String, key: &str, v: &Option<chrono::NaiveDate>, first: &mut bool) {
    w_key(out, key, first);
    match v {
        Some(d) => {
            out.push('"');
            out.push_str(&d.format("%Y-%m-%d").to_string());
            out.push('"');
        }
        None => w_null(out),
    }
}

pub fn role_to_json(r: &Role, out: &mut String) {
    out.push('{');
    let mut first = true;
    w_opt_i32(out, "id", r.id, &mut first);
    w_opt_str(out, "name", &r.name, &mut first);
    w_opt_str(out, "description", &r.description, &mut first);
    out.push('}');
}

pub fn user_to_json(u: &User, out: &mut String) {
    out.push('{');
    let mut first = true;
    w_opt_i32(out, "id", u.id, &mut first);
    w_opt_str(out, "firstName", &u.first_name, &mut first);
    w_opt_str(out, "lastName", &u.last_name, &mut first);
    w_opt_str(out, "email", &u.email, &mut first);
    w_date(out, "birthday", &u.birthday, &mut first);
    w_opt_str(out, "language", &u.language, &mut first);
    w_opt_str(out, "accountName", &u.account_name, &mut first);
    w_bool(out, "active", u.active, &mut first);
    w_key(out, "roles", &mut first);
    match &u.roles {
        Some(roles) => {
            out.push('[');
            for (i, r) in roles.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                role_to_json(r, out);
            }
            out.push(']');
        }
        None => w_null(out),
    }
    w_key(out, "userGroups", &mut first);
    match &u.user_group_ids {
        Some(groups) => {
            out.push('[');
            for (i, g) in groups.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                out.push_str(&g.to_string());
            }
            out.push(']');
        }
        None => w_null(out),
    }
    out.push('}');
}

pub fn group_to_json(g: &UserGroup, out: &mut String) {
    out.push('{');
    let mut first = true;
    w_opt_i32(out, "id", g.id, &mut first);
    w_opt_str(out, "name", &g.name, &mut first);
    w_key(out, "owner", &mut first);
    match &g.owner {
        Some(o) => user_to_json(o, out),
        None => w_null(out),
    }
    w_key(out, "members", &mut first);
    match &g.members {
        Some(members) => {
            out.push('[');
            for (i, m) in members.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                user_to_json(m, out);
            }
            out.push(']');
        }
        None => w_null(out),
    }
    w_key(out, "roles", &mut first);
    match &g.roles {
        Some(roles) => {
            out.push('[');
            for (i, r) in roles.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                role_to_json(r, out);
            }
            out.push(']');
        }
        None => w_null(out),
    }
    out.push('}');
}

pub fn extent_to_json(e: &Extent, out: &mut String) {
    out.push('{');
    let mut first = true;
    w_opt_i32(out, "id", e.id, &mut first);
    w_opt_point(out, "lowerLeft", &e.lower_left, &mut first);
    w_opt_point(out, "upperRight", &e.upper_right, &mut first);
    out.push('}');
}

pub fn tilegrid_to_json(t: &TileGrid, out: &mut String) {
    out.push('{');
    let mut first = true;
    w_opt_i32(out, "id", t.id, &mut first);
    w_opt_str(out, "type", &t.grid_type, &mut first);
    w_opt_point(out, "tileGridOrigin", &t.origin, &mut first);
    w_key(out, "tileGridExtent", &mut first);
    match &t.extent {
        Some(e) => extent_to_json(e, out),
        None => w_null(out),
    }
    w_opt_i32(out, "tileSize", t.tile_size, &mut first);
    w_key(out, "tileGridResolutions", &mut first);
    match &t.resolutions {
        Some(list) => {
            out.push('[');
            for (i, r) in list.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                match r {
                    Some(v) => out.push_str(&java_double_to_string(*v)),
                    None => w_null(out),
                }
            }
            out.push(']');
        }
        None => w_null(out),
    }
    if t.is_wmts {
        w_key(out, "matrixIds", &mut first);
        match &t.matrix_ids {
            Some(list) => {
                out.push('[');
                for (i, m) in list.iter().enumerate() {
                    if i > 0 {
                        out.push(',');
                    }
                    match m {
                        Some(s) => w_str(out, s),
                        None => w_null(out),
                    }
                }
                out.push(']');
            }
            None => w_null(out),
        }
    }
    out.push('}');
}

fn prop_value_to_json(out: &mut String, v: &PropValue) {
    match v {
        PropValue::Str(s) => w_str(out, s),
        PropValue::Long(l) => out.push_str(&l.to_string()),
        PropValue::Double(d) => out.push_str(&java_double_to_string(*d)),
        PropValue::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
    }
}

fn raw_value_to_json(out: &mut String, v: &Value) {
    match v {
        Value::Null => out.push_str("null"),
        Value::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        Value::Number(n) => out.push_str(&java_number_to_string(n)),
        Value::String(s) => w_str(out, s),
        Value::Array(arr) => {
            out.push('[');
            for (i, item) in arr.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                raw_value_to_json(out, item);
            }
            out.push(']');
        }
        Value::Object(map) => {
            out.push('{');
            let mut first = true;
            for (k, val) in map.iter() {
                if !first {
                    out.push(',');
                }
                first = false;
                w_str(out, k);
                out.push(':');
                raw_value_to_json(out, val);
            }
            out.push('}');
        }
    }
}

pub fn appearance_to_json(a: &LayerAppearance, out: &mut String) {
    out.push('{');
    let mut first = true;
    w_opt_i32(out, "id", a.id, &mut first);
    w_opt_str(out, "attribution", &a.attribution, &mut first);
    w_opt_bool(out, "hoverable", a.hoverable, &mut first);
    w_opt_bool(out, "clickable", a.clickable, &mut first);
    w_opt_str(out, "hoverTemplate", &a.hover_template, &mut first);
    w_key(out, "properties", &mut first);
    match &a.properties {
        PropState::Null => w_null(out),
        PropState::Raw(raw) => {
            out.push('{');
            for (i, (k, v)) in raw.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                w_str(out, k);
                out.push(':');
                raw_value_to_json(out, v);
            }
            out.push('}');
        }
        PropState::Loaded(props) => {
            out.push('{');
            for (i, (k, v)) in props.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                w_str(out, k);
                out.push(':');
                prop_value_to_json(out, v);
            }
            out.push('}');
        }
    }
    w_opt_str(out, "name", &a.name, &mut first);
    w_opt_f64(out, "maxResolution", a.max_resolution, &mut first);
    w_opt_f64(out, "minResolution", a.min_resolution, &mut first);
    w_opt_f64(out, "opacity", a.opacity, &mut first);
    w_opt_bool(out, "visible", a.visible, &mut first);
    out.push('}');
}

pub fn datasource_to_json(d: &DataSource, out: &mut String) {
    out.push('{');
    let mut first = true;
    w_opt_i32(out, "id", d.id, &mut first);
    w_opt_str(out, "name", &d.name, &mut first);
    w_opt_str(out, "type", &d.ds_type, &mut first);
    w_opt_str(out, "url", &d.url, &mut first);
    w_opt_str(out, "format", &d.format, &mut first);
    match d.kind {
        DsKind::ImageWms | DsKind::TileWms => {
            w_i32(out, "width", d.width, &mut first);
            w_i32(out, "height", d.height, &mut first);
            w_opt_str(out, "version", &d.version, &mut first);
            w_opt_str(out, "layerNames", &d.layer_names, &mut first);
            w_opt_str(out, "layerStyles", &d.layer_styles, &mut first);
            w_opt_bool(out, "requestableByPath", d.requestable_by_path, &mut first);
            w_opt_str(out, "customRequestPath", &d.custom_request_path, &mut first);
            if d.kind == DsKind::TileWms {
                w_key(out, "tileGrid", &mut first);
                match &d.tile_grid {
                    Some(t) => tilegrid_to_json(t, out),
                    None => w_null(out),
                }
                w_opt_bool(out, "requestWithTiled", d.request_with_tiled, &mut first);
            }
        }
        DsKind::Wfs => {
            w_opt_str(out, "version", &d.version, &mut first);
            w_opt_str(out, "typeName", &d.type_name, &mut first);
            w_opt_str(out, "typeNames", &d.type_names, &mut first);
        }
        DsKind::Wmts => {
            w_key(out, "tileGrid", &mut first);
            match &d.tile_grid {
                Some(t) => tilegrid_to_json(t, out),
                None => w_null(out),
            }
            w_key(out, "urls", &mut first);
            match &d.urls {
                Some(list) => {
                    out.push('[');
                    for (i, u) in list.iter().enumerate() {
                        if i > 0 {
                            out.push(',');
                        }
                        match u {
                            Some(s) => w_str(out, s),
                            None => w_null(out),
                        }
                    }
                    out.push(']');
                }
                None => w_null(out),
            }
            w_opt_str(out, "wmtsLayer", &d.wmts_layer, &mut first);
            w_opt_str(out, "wmtsStyle", &d.wmts_style, &mut first);
            w_opt_str(out, "projection", &d.projection, &mut first);
            w_opt_str(out, "matrixSet", &d.matrix_set, &mut first);
            w_opt_str(out, "requestEncoding", &d.request_encoding, &mut first);
            w_opt_str(out, "capabilitiesUrl", &d.capabilities_url, &mut first);
        }
        DsKind::Xyz => {
            w_opt_point(out, "center", &d.center, &mut first);
            w_key(out, "extent", &mut first);
            match &d.extent {
                Some(e) => extent_to_json(e, out),
                None => w_null(out),
            }
            w_key(out, "resolutions", &mut first);
            match &d.resolutions {
                Some(list) => {
                    out.push('[');
                    for (i, p) in list.iter().enumerate() {
                        if i > 0 {
                            out.push(',');
                        }
                        match p {
                            Some(pt) => w_point(out, pt),
                            None => w_null(out),
                        }
                    }
                    out.push(']');
                }
                None => w_null(out),
            }
            w_opt_i32(out, "tileSize", d.tile_size, &mut first);
        }
        DsKind::Base => {}
    }
    out.push('}');
}

pub fn layer_to_json(l: &Layer, out: &mut String) {
    out.push('{');
    let mut first = true;
    w_opt_i32(out, "id", l.id, &mut first);
    w_opt_str(out, "name", &l.name, &mut first);
    w_opt_str(out, "description", &l.description, &mut first);
    w_key(out, "source", &mut first);
    match &l.source {
        Some(s) => datasource_to_json(s, out),
        None => w_null(out),
    }
    w_key(out, "appearance", &mut first);
    match &l.appearance {
        Some(a) => appearance_to_json(a, out),
        None => w_null(out),
    }
    out.push('}');
}

// ---------------------------------------------------------------------------
// Deserialization (Jackson semantics)
// ---------------------------------------------------------------------------

/// Context needed to resolve `userGroups` id references like the original's
/// PersistentObjectIdResolver does (loadById + READ permission check).
pub struct ApplyCtx<'a> {
    pub client: &'a tokio_postgres::Client,
    pub principal_is_admin: bool,
    pub principal_member_of: &'a [i32],
    pub group_perms: &'a std::collections::HashMap<i32, Vec<Permission>>,
}

fn obj(v: &Value) -> JResult<&Map<String, Value>> {
    match v {
        Value::Object(m) => Ok(m),
        _ => Err(JacksonError),
    }
}

fn check_known(key: &str, known: &[&str]) -> JResult<()> {
    if IGNORABLE.contains(&key) || known.contains(&key) {
        Ok(())
    } else {
        Err(JacksonError)
    }
}

// --- scalar coercions (Jackson StdDeserializer behaviour) ---

fn to_opt_string(v: &Value) -> JResult<Option<String>> {
    match v {
        Value::Null => Ok(None),
        Value::String(s) => Ok(Some(s.clone())),
        Value::Number(n) => Ok(Some(java_number_to_string(n))),
        Value::Bool(b) => Ok(Some(b.to_string())),
        _ => Err(JacksonError),
    }
}

fn to_opt_i32(v: &Value) -> JResult<Option<i32>> {
    match v {
        Value::Null => Ok(None),
        Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                if i > i32::MAX as i64 || i < i32::MIN as i64 {
                    return Err(JacksonError); // InputCoercionException
                }
                Ok(Some(i as i32))
            } else if let Some(f) = n.as_f64() {
                if f.is_finite() && f >= i32::MIN as f64 - 1.0 && f <= i32::MAX as f64 + 1.0 {
                    Ok(Some(f as i32)) // truncation toward zero
                } else {
                    Err(JacksonError)
                }
            } else {
                Err(JacksonError)
            }
        }
        Value::String(s) => {
            let t = s.trim();
            match t.parse::<i64>() {
                Ok(i) => {
                    if i > i32::MAX as i64 || i < i32::MIN as i64 {
                        Err(JacksonError)
                    } else {
                        Ok(Some(i as i32))
                    }
                }
                Err(_) => match t.parse::<f64>() {
                    Ok(f) if f.is_finite() => Ok(Some(f as i32)),
                    _ => Err(JacksonError),
                },
            }
        }
        Value::Bool(b) => Ok(Some(if *b { 1 } else { 0 })),
        _ => Err(JacksonError),
    }
}

fn to_prim_i32(v: &Value) -> JResult<i32> {
    Ok(to_opt_i32(v)?.unwrap_or(0))
}

fn to_opt_f64(v: &Value) -> JResult<Option<f64>> {
    match v {
        Value::Null => Ok(None),
        Value::Number(n) => n.as_f64().ok_or(JacksonError),
        Value::String(s) => {
            let t = s.trim();
            if t.eq_ignore_ascii_case("nan") {
                return Ok(Some(f64::NAN));
            }
            match t.parse::<f64>() {
                Ok(f) => Ok(Some(f)),
                Err(_) => Err(JacksonError),
            }
        }
        Value::Bool(b) => Ok(Some(if *b { 1.0 } else { 0.0 })),
        _ => Err(JacksonError),
    }
}

fn to_opt_bool(v: &Value) -> JResult<Option<bool>> {
    match v {
        Value::Null => Ok(None),
        Value::Bool(b) => Ok(Some(*b)),
        Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                Ok(Some(i != 0))
            } else if let Some(f) = n.as_f64() {
                Ok(Some(f != 0.0))
            } else {
                Err(JacksonError)
            }
        }
        Value::String(s) => {
            let t = s.trim();
            if t.eq_ignore_ascii_case("true") {
                Ok(Some(true))
            } else if t.eq_ignore_ascii_case("false") || t.is_empty() {
                Ok(Some(false))
            } else {
                Err(JacksonError)
            }
        }
        _ => Err(JacksonError),
    }
}

fn to_prim_bool(v: &Value) -> JResult<bool> {
    Ok(to_opt_bool(v)?.unwrap_or(false))
}

fn to_opt_date(v: &Value) -> JResult<Option<chrono::NaiveDate>> {
    match v {
        Value::Null => Ok(None),
        Value::String(s) => {
            let t = s.trim();
            if let Ok(d) = chrono::NaiveDate::parse_from_str(t, "%Y-%m-%d") {
                return Ok(Some(d));
            }
            // Joda's local date parser accepts non zero-padded parts and a
            // trailing time part; approximate with a manual split.
            let date_part = t.split(['T', ' ']).next().unwrap_or(t);
            let parts: Vec<&str> = date_part.split('-').collect();
            if parts.len() == 3 {
                if let (Ok(y), Ok(m), Ok(d)) = (
                    parts[0].parse::<i32>(),
                    parts[1].parse::<u32>(),
                    parts[2].parse::<u32>(),
                ) {
                    if let Some(date) = chrono::NaiveDate::from_ymd_opt(y, m, d) {
                        return Ok(Some(date));
                    }
                }
            }
            Err(JacksonError)
        }
        _ => Err(JacksonError),
    }
}

fn to_opt_locale(v: &Value) -> JResult<Option<String>> {
    match v {
        Value::Null => Ok(None),
        Value::String(s) => Ok(Some(normalize_locale(s))),
        _ => Err(JacksonError),
    }
}

fn to_opt_point(v: &Value) -> JResult<Option<Point>> {
    match v {
        Value::Null => Ok(None),
        Value::Object(m) => {
            let mut p = Point { x: 0.0, y: 0.0 };
            for (k, val) in m.iter() {
                match k.as_str() {
                    "x" => p.x = to_opt_f64(val)?.unwrap_or(0.0),
                    "y" => p.y = to_opt_f64(val)?.unwrap_or(0.0),
                    "location" => {} // read-only property, silently skipped
                    _ => return Err(JacksonError),
                }
            }
            Ok(Some(p))
        }
        _ => Err(JacksonError),
    }
}

// --- entity deserialization ---

const ROLE_PROPS: &[&str] = &["id", "name", "description"];

pub fn apply_role(r: &mut Role, v: &Value) -> JResult<()> {
    let m = obj(v)?;
    for (k, val) in m.iter() {
        check_known(k, ROLE_PROPS)?;
        match k.as_str() {
            "id" => r.id = to_opt_i32(val)?,
            "name" => r.name = to_opt_string(val)?,
            "description" => r.description = to_opt_string(val)?,
            _ => {}
        }
    }
    Ok(())
}

fn build_role(v: &Value) -> JResult<Role> {
    let mut r = Role::new_fresh();
    apply_role(&mut r, v)?;
    Ok(r)
}

const EXTENT_PROPS: &[&str] = &["id", "lowerLeft", "upperRight"];

pub fn apply_extent(e: &mut Extent, v: &Value) -> JResult<()> {
    let m = obj(v)?;
    for (k, val) in m.iter() {
        check_known(k, EXTENT_PROPS)?;
        match k.as_str() {
            "id" => e.id = to_opt_i32(val)?,
            "lowerLeft" => e.lower_left = to_opt_point(val)?,
            "upperRight" => e.upper_right = to_opt_point(val)?,
            _ => {}
        }
    }
    Ok(())
}

fn build_extent(v: &Value) -> JResult<Extent> {
    let mut e = Extent::new_fresh();
    apply_extent(&mut e, v)?;
    Ok(e)
}

const TILEGRID_PROPS: &[&str] =
    &["id", "type", "tileGridOrigin", "tileGridExtent", "tileSize", "tileGridResolutions"];
const WMTS_TILEGRID_PROPS: &[&str] = &[
    "id",
    "type",
    "tileGridOrigin",
    "tileGridExtent",
    "tileSize",
    "tileGridResolutions",
    "matrixIds",
];

pub fn apply_tilegrid(t: &mut TileGrid, v: &Value) -> JResult<()> {
    let m = obj(v)?;
    let known = if t.is_wmts { WMTS_TILEGRID_PROPS } else { TILEGRID_PROPS };
    for (k, val) in m.iter() {
        check_known(k, known)?;
        match k.as_str() {
            "id" => t.id = to_opt_i32(val)?,
            "type" => t.grid_type = to_opt_string(val)?,
            "tileGridOrigin" => t.origin = to_opt_point(val)?,
            "tileGridExtent" => {
                t.extent = match val {
                    Value::Null => None,
                    other => Some(Box::new(build_extent(other)?)),
                }
            }
            "tileSize" => t.tile_size = to_opt_i32(val)?,
            "tileGridResolutions" => {
                t.resolutions = match val {
                    Value::Null => None,
                    Value::Array(arr) => {
                        let mut list = Vec::new();
                        for item in arr {
                            list.push(to_opt_f64(item)?);
                        }
                        Some(list)
                    }
                    _ => return Err(JacksonError),
                }
            }
            "matrixIds" => {
                t.matrix_ids = match val {
                    Value::Null => None,
                    Value::Array(arr) => {
                        let mut list = Vec::new();
                        for item in arr {
                            list.push(to_opt_string(item)?);
                        }
                        Some(list)
                    }
                    _ => return Err(JacksonError),
                }
            }
            _ => {}
        }
    }
    Ok(())
}

fn build_tilegrid(v: &Value, is_wmts: bool) -> JResult<TileGrid> {
    let mut t = TileGrid::new_fresh(is_wmts);
    apply_tilegrid(&mut t, v)?;
    Ok(t)
}

const APPEARANCE_PROPS: &[&str] = &[
    "id",
    "attribution",
    "hoverable",
    "clickable",
    "hoverTemplate",
    "properties",
    "name",
    "maxResolution",
    "minResolution",
    "opacity",
    "visible",
];

pub fn apply_appearance(a: &mut LayerAppearance, v: &Value) -> JResult<()> {
    let m = obj(v)?;
    for (k, val) in m.iter() {
        check_known(k, APPEARANCE_PROPS)?;
        match k.as_str() {
            "id" => a.id = to_opt_i32(val)?,
            "attribution" => a.attribution = to_opt_string(val)?,
            "hoverable" => a.hoverable = to_opt_bool(val)?,
            "clickable" => a.clickable = to_opt_bool(val)?,
            "hoverTemplate" => a.hover_template = to_opt_string(val)?,
            "properties" => match val {
                Value::Null => {
                    a.properties = PropState::Null;
                }
                Value::Object(pm) => {
                    let mut raw: Vec<(String, Value)> = Vec::new();
                    for (pk, pv) in pm.iter() {
                        if let Some(pos) = raw.iter().position(|(k, _)| k == pk) {
                            raw[pos].1 = pv.clone(); // LinkedHashMap.put replaces value
                        } else {
                            raw.push((pk.clone(), pv.clone()));
                        }
                    }
                    a.properties = PropState::Raw(raw);
                }
                _ => return Err(JacksonError),
            },
            "name" => a.name = to_opt_string(val)?,
            "maxResolution" => a.max_resolution = to_opt_f64(val)?,
            "minResolution" => a.min_resolution = to_opt_f64(val)?,
            "opacity" => a.opacity = to_opt_f64(val)?,
            "visible" => a.visible = to_opt_bool(val)?,
            _ => {}
        }
    }
    Ok(())
}

fn build_appearance(v: &Value) -> JResult<LayerAppearance> {
    let mut a = LayerAppearance::new_fresh();
    apply_appearance(&mut a, v)?;
    Ok(a)
}

const USER_PROPS: &[&str] = &[
    "id",
    "firstName",
    "lastName",
    "email",
    "birthday",
    "language",
    "accountName",
    "password",
    "active",
    "roles",
    "userGroups",
];

pub async fn apply_user(u: &mut User, v: &Value, ctx: &ApplyCtx<'_>) -> JResult<()> {
    let m = obj(v)?;
    for (k, val) in m.iter() {
        check_known(k, USER_PROPS)?;
        match k.as_str() {
            "id" => u.id = to_opt_i32(val)?,
            "firstName" => u.first_name = to_opt_string(val)?,
            "lastName" => u.last_name = to_opt_string(val)?,
            "email" => u.email = to_opt_string(val)?,
            "birthday" => u.birthday = to_opt_date(val)?,
            "language" => u.language = to_opt_locale(val)?,
            "accountName" => u.account_name = to_opt_string(val)?,
            "password" => u.password = to_opt_string(val)?,
            "active" => u.active = to_prim_bool(val)?,
            "roles" => match val {
                Value::Null => u.roles = None,
                Value::Array(arr) => {
                    let mut roles = Vec::new();
                    for item in arr {
                        if item.is_null() {
                            // null element ends up in the set and fails at flush
                            roles.push(Role::new_fresh());
                        } else {
                            roles.push(build_role(item)?);
                        }
                    }
                    dedup_roles(&mut roles);
                    u.roles = Some(roles);
                }
                _ => return Err(JacksonError),
            },
            "userGroups" => match val {
                Value::Null => u.user_group_ids = None,
                Value::Array(arr) => {
                    let mut ids: Vec<i32> = Vec::new();
                    for item in arr {
                        let id_val = match item {
                            Value::Object(om) => match om.get("id") {
                                Some(iv) => iv.clone(),
                                None => return Err(JacksonError),
                            },
                            other => other.clone(),
                        };
                        let gid = match to_opt_i32(&id_val)? {
                            Some(i) => i,
                            None => return Err(JacksonError),
                        };
                        // resolveId: the group must exist (a checked error here
                        // mirrors the JsonMappingException wrapping the
                        // ObjectNotFoundException), and non-admin principals
                        // need READ permission on it (loadById @PostAuthorize).
                        let exists = crate::db::exists(ctx.client, "usergroups", gid)
                            .await
                            .map_err(|_| JacksonError)?;
                        if !exists {
                            return Err(JacksonError);
                        }
                        if !ctx.principal_is_admin {
                            let readable = ctx.principal_member_of.contains(&gid)
                                || ctx
                                    .group_perms
                                    .get(&gid)
                                    .map(|ps| {
                                        ps.contains(&Permission::Read) || ps.contains(&Permission::Admin)
                                    })
                                    .unwrap_or(false);
                            if !readable {
                                return Err(JacksonError);
                            }
                        }
                        if !ids.contains(&gid) {
                            ids.push(gid);
                        }
                    }
                    u.user_group_ids = Some(ids);
                }
                _ => return Err(JacksonError),
            },
            _ => {}
        }
    }
    Ok(())
}

pub fn dedup_roles(roles: &mut Vec<Role>) {
    let mut out: Vec<Role> = Vec::new();
    for r in roles.drain(..) {
        if !out.iter().any(|o| o.java_equals(&r)) {
            out.push(r);
        }
    }
    *roles = out;
}

pub fn dedup_users(users: &mut Vec<User>) {
    let mut out: Vec<User> = Vec::new();
    for u in users.drain(..) {
        if !out.iter().any(|o| o.java_equals(&u)) {
            out.push(u);
        }
    }
    *users = out;
}

pub async fn build_user(v: &Value, ctx: &ApplyCtx<'_>) -> JResult<User> {
    let mut u = User::new_fresh();
    apply_user(&mut u, v, ctx).await?;
    Ok(u)
}

const GROUP_PROPS: &[&str] = &["id", "name", "owner", "members", "roles"];

pub async fn apply_group(g: &mut UserGroup, v: &Value, ctx: &ApplyCtx<'_>) -> JResult<()> {
    let m = obj(v)?;
    for (k, val) in m.iter() {
        check_known(k, GROUP_PROPS)?;
        match k.as_str() {
            "id" => g.id = to_opt_i32(val)?,
            "name" => g.name = to_opt_string(val)?,
            "owner" => {
                g.owner = match val {
                    Value::Null => None,
                    other => Some(Box::new(build_user(other, ctx).await?)),
                }
            }
            "members" => match val {
                Value::Null => g.members = None,
                Value::Array(arr) => {
                    let mut members = Vec::new();
                    for item in arr {
                        if item.is_null() {
                            members.push(User::new_fresh());
                        } else {
                            members.push(build_user(item, ctx).await?);
                        }
                    }
                    dedup_users(&mut members);
                    g.members = Some(members);
                }
                _ => return Err(JacksonError),
            },
            "roles" => match val {
                Value::Null => g.roles = None,
                Value::Array(arr) => {
                    let mut roles = Vec::new();
                    for item in arr {
                        if item.is_null() {
                            roles.push(Role::new_fresh());
                        } else {
                            roles.push(build_role(item)?);
                        }
                    }
                    dedup_roles(&mut roles);
                    g.roles = Some(roles);
                }
                _ => return Err(JacksonError),
            },
            _ => {}
        }
    }
    Ok(())
}

pub async fn build_group(v: &Value, ctx: &ApplyCtx<'_>) -> JResult<UserGroup> {
    let mut g = UserGroup::new_fresh();
    apply_group(&mut g, v, ctx).await?;
    Ok(g)
}

const LAYER_PROPS: &[&str] = &["id", "name", "description", "source", "appearance"];

pub async fn apply_layer(l: &mut Layer, v: &Value, ctx: &ApplyCtx<'_>) -> JResult<()> {
    let m = obj(v)?;
    for (k, val) in m.iter() {
        check_known(k, LAYER_PROPS)?;
        match k.as_str() {
            "id" => l.id = to_opt_i32(val)?,
            "name" => l.name = to_opt_string(val)?,
            "description" => l.description = to_opt_string(val)?,
            "source" => {
                // LayerDataSource is abstract without type information: any
                // non-null value fails deserialization like in the original.
                if !val.is_null() {
                    return Err(JacksonError);
                }
                l.source = None;
            }
            "appearance" => {
                l.appearance = match val {
                    Value::Null => None,
                    other => Some(Box::new(build_appearance(other)?)),
                }
            }
            _ => {}
        }
    }
    Ok(())
}

pub async fn build_layer(v: &Value, ctx: &ApplyCtx<'_>) -> JResult<Layer> {
    let mut l = Layer::new_fresh();
    apply_layer(&mut l, v, ctx).await?;
    Ok(l)
}

fn ds_props(kind: DsKind) -> &'static [&'static str] {
    match kind {
        DsKind::ImageWms => &[
            "id",
            "name",
            "type",
            "url",
            "format",
            "width",
            "height",
            "version",
            "layerNames",
            "layerStyles",
            "requestableByPath",
            "customRequestPath",
        ],
        DsKind::TileWms => &[
            "id",
            "name",
            "type",
            "url",
            "format",
            "width",
            "height",
            "version",
            "layerNames",
            "layerStyles",
            "requestableByPath",
            "customRequestPath",
            "tileGrid",
            "requestWithTiled",
        ],
        DsKind::Wfs => &["id", "name", "type", "url", "format", "version", "typeName", "typeNames"],
        DsKind::Wmts => &[
            "id",
            "name",
            "type",
            "url",
            "format",
            "tileGrid",
            "urls",
            "wmtsLayer",
            "wmtsStyle",
            "projection",
            "matrixSet",
            "requestEncoding",
            "capabilitiesUrl",
        ],
        DsKind::Xyz => &[
            "id",
            "name",
            "type",
            "url",
            "format",
            "center",
            "extent",
            "resolutions",
            "tileSize",
        ],
        DsKind::Base => &["id", "name", "type", "url", "format"],
    }
}

pub async fn apply_datasource(d: &mut DataSource, v: &Value, ctx: &ApplyCtx<'_>) -> JResult<()> {
    let m = obj(v)?;
    let known = ds_props(d.kind);
    for (k, val) in m.iter() {
        check_known(k, known)?;
        match k.as_str() {
            "id" => d.id = to_opt_i32(val)?,
            "name" => d.name = to_opt_string(val)?,
            "type" => d.ds_type = to_opt_string(val)?,
            "url" => d.url = to_opt_string(val)?,
            "format" => d.format = to_opt_string(val)?,
            "width" => d.width = to_prim_i32(val)?,
            "height" => d.height = to_prim_i32(val)?,
            "version" => d.version = to_opt_string(val)?,
            "layerNames" => d.layer_names = to_opt_string(val)?,
            "layerStyles" => d.layer_styles = to_opt_string(val)?,
            "requestableByPath" => d.requestable_by_path = to_opt_bool(val)?,
            "customRequestPath" => d.custom_request_path = to_opt_string(val)?,
            "requestWithTiled" => d.request_with_tiled = to_opt_bool(val)?,
            "typeName" => d.type_name = to_opt_string(val)?,
            "typeNames" => d.type_names = to_opt_string(val)?,
            "wmtsLayer" => d.wmts_layer = to_opt_string(val)?,
            "wmtsStyle" => d.wmts_style = to_opt_string(val)?,
            "projection" => d.projection = to_opt_string(val)?,
            "matrixSet" => d.matrix_set = to_opt_string(val)?,
            "requestEncoding" => d.request_encoding = to_opt_string(val)?,
            "capabilitiesUrl" => d.capabilities_url = to_opt_string(val)?,
            "tileSize" => d.tile_size = to_opt_i32(val)?,
            "center" => d.center = to_opt_point(val)?,
            "tileGrid" => {
                let is_wmts = d.kind == DsKind::Wmts;
                d.tile_grid = match val {
                    Value::Null => None,
                    other => Some(Box::new(build_tilegrid(other, is_wmts)?)),
                }
            }
            "extent" => {
                d.extent = match val {
                    Value::Null => None,
                    other => Some(Box::new(build_extent(other)?)),
                }
            }
            "urls" => match val {
                Value::Null => d.urls = None,
                Value::Array(arr) => {
                    let mut list = Vec::new();
                    for item in arr {
                        list.push(to_opt_string(item)?);
                    }
                    d.urls = Some(list);
                }
                _ => return Err(JacksonError),
            },
            "resolutions" => match val {
                Value::Null => d.resolutions = None,
                Value::Array(arr) => {
                    let mut list = Vec::new();
                    for item in arr {
                        if item.is_null() {
                            list.push(None);
                        } else {
                            list.push(to_opt_point(item)?);
                        }
                    }
                    d.resolutions = Some(list);
                }
                _ => return Err(JacksonError),
            },
            _ => {}
        }
    }
    Ok(())
}

/// Mimic `JsonNode.get("id").asInt()`.
pub fn json_id_as_int(v: &Value) -> i32 {
    match v {
        Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                i as i32 // Java (int) truncation
            } else if let Some(f) = n.as_f64() {
                f as i32
            } else {
                0
            }
        }
        Value::String(s) => {
            let t = s.trim();
            match t.parse::<i64>() {
                Ok(i) => i as i32,
                Err(_) => match t.parse::<f64>() {
                    Ok(f) if f.is_finite() => f as i32,
                    _ => 0,
                },
            }
        }
        Value::Bool(b) => {
            if *b {
                1
            } else {
                0
            }
        }
        _ => 0,
    }
}

