pub async fn load_appearances(
    c: &tokio_postgres::Client,
    ids: Option<&[i32]>,
) -> Result<Vec<LayerAppearance>, tokio_postgres::Error> {
    let sql = if let Some(ids) = ids {
        let _ = ids;
        "SELECT id, created, modified, attribution, clickable, hovertemplate, hoverable, \
         maxresolution, minresolution, name, opacity, visible \
         FROM layerappearances WHERE id = ANY($1) ORDER BY id"
    } else {
        "SELECT id, created, modified, attribution, clickable, hovertemplate, hoverable, \
         maxresolution, minresolution, name, opacity, visible \
         FROM layerappearances ORDER BY id"
    };
    let rows = if let Some(ids) = ids {
        c.query(sql, &[&ids]).await?
    } else {
        c.query(sql, &[]).await?
    };
    let mut apps: Vec<LayerAppearance> = rows.iter().map(appearance_from_row).collect();
    let aids: Vec<i32> = apps.iter().filter_map(|a| a.id).collect();
    if !aids.is_empty() {
        let prop_rows = c
            .query(
                "SELECT appearance_id, property, value FROM layerappearances_properties WHERE appearance_id = ANY($1) ORDER BY property",
                &[&aids],
            )
            .await?;
        for a in apps.iter_mut() {
            let aid = a.id.unwrap_or(-1);
            let props: Vec<(String, PropValue)> = prop_rows
                .iter()
                .filter(|r| r.get::<_, i32>("appearance_id") == aid)
                .map(|r| {
                    let key: String = r.get("property");
                    let val: Option<String> = r.get("value");
                    (key.clone(), match val {
                        Some(s) => PropValue::from_db_string(&s),
                        None => PropValue::Str("null".to_string()),
                    })
                })
                .collect();
            a.properties = PropState::Loaded(props);
        }
    }
    Ok(apps)
}

