/// Count-only variant used to decide whether a restricted data source query
/// would blow up (the original fails with 500 as soon as a row is transformed
/// into the abstract LayerDataSource class).
pub async fn count_datasources_where(
    c: &tokio_postgres::Client,
    where_sql: &str,
    params: &[&(dyn tokio_postgres::types::ToSql + Sync)],
