async fn datasources_from_rows(
    c: &tokio_postgres::Client,
    rows: &[Row],
) -> Result<Vec<DataSource>, String> {
    let mut dss: Vec<DataSource> = rows.iter().map(datasource_from_row).collect();
    if dss.is_empty() {
        return Ok(dss);
    }
    let mut tilegrid_ids: Vec<i32> = Vec::new();
    let mut xyz_extent_ids: Vec<i32> = Vec::new();
    let mut wmts_ids: Vec<i32> = Vec::new();
    let mut xyz_ids: Vec<i32> = Vec::new();
    for (ds, row) in dss.iter_mut().zip(rows.iter()) {
        match ds.kind {
            DsKind::TileWms => {
                if let Some(gid) = row.get::<_, Option<i32>>("tw_tilegrid_id") {
                    tilegrid_ids.push(gid);
                    let mut g = TileGrid::from_db(false);
                    g.id = Some(gid);
                    ds.tile_grid = Some(Box::new(g));
                }
            }
            DsKind::Wmts => {
                wmts_ids.push(ds.id.unwrap_or(-1));
                if let Some(gid) = row.get::<_, Option<i32>>("wmts_tilegrid_id") {
                    tilegrid_ids.push(gid);
                    let mut g = TileGrid::from_db(true);
                    g.id = Some(gid);
                    ds.tile_grid = Some(Box::new(g));
                }
            }
            DsKind::Xyz => {
                xyz_ids.push(ds.id.unwrap_or(-1));
                if let Some(eid) = row.get::<_, Option<i32>>("xyz_extent_id") {
                    xyz_extent_ids.push(eid);
                }
            }
            _ => {}
        }
    }
    let grids = load_tilegrids(c, &tilegrid_ids).await?;
    let url_rows = if wmts_ids.is_empty() {
        Vec::new()
    } else {
        c.query(
            "SELECT wmtslayerdatasources_id, urls FROM wmtslayerdatasources_urls WHERE wmtslayerdatasources_id = ANY($1)",
            &[&wmts_ids],
        )
        .await
        .map_err(|e| e.to_string())?
    };
    let xyz_extents = load_extents(c, &xyz_extent_ids).await?;
    let res_rows = if xyz_ids.is_empty() {
        Vec::new()
    } else {
        c.query(
            "SELECT xyzlayerdatasrc_id, resolution, idx FROM xyzlayerdatasrc_resolution WHERE xyzlayerdatasrc_id = ANY($1) ORDER BY idx",
            &[&xyz_ids],
        )
        .await
        .map_err(|e| e.to_string())?
    };
    for (ds, row) in dss.iter_mut().zip(rows.iter()) {
        let id = ds.id.unwrap_or(-1);
        match ds.kind {
            DsKind::TileWms | DsKind::Wmts => {
                let gid = ds.tile_grid.as_ref().and_then(|g| g.id);
                if let Some(gid) = gid {
                    if let Some(g) = grids.iter().find(|g| g.id == Some(gid)) {
                        ds.tile_grid = Some(Box::new(g.clone()));
                    }
                }
                if ds.kind == DsKind::Wmts {
                    ds.urls = Some(
                        url_rows
                            .iter()
                            .filter(|r| r.get::<_, i32>("wmtslayerdatasources_id") == id)
                            .map(|r| r.get::<_, Option<String>>("urls"))
                            .collect(),
                    );
                }
            }
            DsKind::Xyz => {
                if let Some(eid) = row.get::<_, Option<i32>>("xyz_extent_id") {
                    ds.extent = xyz_extents.iter().find(|e| e.id == Some(eid)).cloned().map(Box::new);
                }
                let mut list = Vec::new();
                for r in res_rows.iter().filter(|r| r.get::<_, i32>("xyzlayerdatasrc_id") == id) {
                    let blob: Option<Vec<u8>> = r.get("resolution");
                    match blob {
                        Some(b) => match javadoc::deserialize_point2d_double(&b) {
                            Some((x, y)) => list.push(Some(Point { x, y })),
                            None => list.push(None),
                        },
                        None => list.push(None),
                    }
                }
                ds.resolutions = Some(list);
            }
            _ => {}
        }
    }
    Ok(dss)
}

pub async fn load_tilegrids(
    c: &tokio_postgres::Client,
    ids: &[i32],
) -> Result<Vec<TileGrid>, String> {
    if ids.is_empty() {
        return Ok(Vec::new());
    }
    let rows = c
        .query(
            "SELECT g.id, g.created, g.modified, g.type, g.tilegridorigin_x, g.tilegridorigin_y, \
             g.tilesize, g.tilegridextent_id, (w.id IS NOT NULL) AS is_wmts \
             FROM tilegrids g LEFT JOIN wmtstilegrids w ON w.id = g.id WHERE g.id = ANY($1) ORDER BY g.id",
            &[&ids],
        )
        .await
        .map_err(|e| e.to_string())?;
    let mut grids: Vec<TileGrid> = rows.iter().map(|r| tilegrid_from_row(r, r.get("is_wmts"))).collect();
    let res_rows = c
        .query(
            "SELECT tilegrid_id, resolution, idx FROM tilegrid_resolution WHERE tilegrid_id = ANY($1) ORDER BY idx",
            &[&ids],
        )
        .await
        .map_err(|e| e.to_string())?;
    let wids: Vec<i32> = grids.iter().filter(|g| g.is_wmts).filter_map(|g| g.id).collect();
    let mat_rows = if wids.is_empty() {
        Vec::new()
    } else {
        c.query(
            "SELECT wmtstilegrids_id, matrixids FROM wmtstilegrids_matrixids WHERE wmtstilegrids_id = ANY($1)",
            &[&wids],
        )
        .await
        .map_err(|e| e.to_string())?
    };
    let ext_ids: Vec<i32> = rows.iter().filter_map(|r| r.get::<_, Option<i32>>("tilegridextent_id")).collect();
    let extents = load_extents(c, &ext_ids).await?;
    for (g, r) in grids.iter_mut().zip(rows.iter()) {
        let gid = g.id.unwrap_or(-1);
        g.resolutions = Some(
            res_rows
                .iter()
                .filter(|rr| rr.get::<_, i32>("tilegrid_id") == gid)
                .map(|rr| rr.get::<_, Option<f64>>("resolution"))
                .collect(),
        );
        if g.is_wmts {
            g.matrix_ids = Some(
                mat_rows
                    .iter()
                    .filter(|rr| rr.get::<_, i32>("wmtstilegrids_id") == gid)
                    .map(|rr| rr.get::<_, Option<String>>("matrixids"))
                    .collect(),
            );
        }
        if let Some(eid) = r.get::<_, Option<i32>>("tilegridextent_id") {
            g.extent = extents.iter().find(|e| e.id == Some(eid)).cloned().map(Box::new);
        }
    }
    Ok(grids)
}

pub async fn load_extents(
    c: &tokio_postgres::Client,
    ids: &[i32],
) -> Result<Vec<Extent>, String> {
    if ids.is_empty() {
        return Ok(Vec::new());
    }
    let rows = c
        .query(
            "SELECT id, created, modified, lowerleft_x, lowerleft_y, upperright_x, upperright_y \
             FROM extents WHERE id = ANY($1) ORDER BY id",
            &[&ids],
        )
        .await
        .map_err(|e| e.to_string())?;
    Ok(rows.iter().map(extent_from_row).collect())
}

pub async fn exists(
    c: &tokio_postgres::Client,
    table: &str,
    id: i32,
) -> Result<bool, tokio_postgres::Error> {
    let sql = format!("SELECT 1 FROM {} WHERE id = $1", table);
    Ok(c.query_opt(&sql, &[&id]).await?.is_some())
}

// ---------------------------------------------------------------------------
// Principal + permissions
// ---------------------------------------------------------------------------

pub struct AuthRow {
    pub id: i32,
    #[allow(dead_code)]
    pub account_name: Option<String>,
    pub active: bool,
    pub password: Option<String>,
}

pub async fn find_auth_user(
    c: &tokio_postgres::Client,
    account_name: &str,
) -> Result<Option<AuthRow>, tokio_postgres::Error> {
    let row = c
        .query_opt(
            "SELECT id, accountname, active, password FROM users WHERE accountname = $1",
            &[&account_name],
        )
        .await?;
    Ok(row.map(|r| AuthRow {
        id: r.get("id"),
        account_name: r.get("accountname"),
        active: r.get::<_, Option<bool>>("active").unwrap_or(false),
        password: r.get("password"),
    }))
}

pub async fn load_role_names(
    c: &tokio_postgres::Client,
    user_id: i32,
) -> Result<Vec<String>, tokio_postgres::Error> {
    let rows = c
        .query(
            "SELECT r.name FROM users_roles ur JOIN roles r ON r.id = ur.role_id WHERE ur.user_id = $1
             UNION
             SELECT r.name FROM usergroups_roles gr
               JOIN user_usergroup ug ON ug.usergroup_id = gr.usergroup_id
               JOIN roles r ON r.id = gr.role_id
             WHERE ug.user_id = $1",
            &[&user_id],
        )
        .await?;
    Ok(rows.iter().map(|r| r.get::<_, String>("name")).collect())
}

pub async fn load_memberships(
    c: &tokio_postgres::Client,
    user_id: i32,
) -> Result<Vec<i32>, tokio_postgres::Error> {
    let rows = c
        .query("SELECT usergroup_id FROM user_usergroup WHERE user_id = $1", &[&user_id])
        .await?;
    Ok(rows.iter().map(|r| r.get("usergroup_id")).collect())
}

pub async fn load_principal_perms(
    c: &tokio_postgres::Client,
    user_id: i32,
    member_of: &[i32],
) -> Result<PrincipalPerms, tokio_postgres::Error> {
    let mut perms = PrincipalPerms {
        user_perms: Default::default(),
        group_perms: Default::default(),
        member_of: member_of.to_vec(),
    };
    let rows = c
        .query(
            "SELECT up.entity_id AS entity_id, pcp.permissions AS permissions
             FROM userpermissions up
             JOIN permissioncollections_permissions pcp ON pcp.permissioncollections_id = up.userpermissions_id
             WHERE up.userpermissions_key = $1",
            &[&user_id],
        )
        .await?;
    for r in &rows {
        let eid: i32 = r.get("entity_id");
        let p: Option<String> = r.get("permissions");
        if let Some(p) = p {
            if let Some(perm) = Permission::from_string(&p) {
                perms.user_perms.entry(eid).or_default().push(perm);
            }
        }
    }
    if !member_of.is_empty() {
        let rows = c
            .query(
                "SELECT gp.entity_id AS entity_id, pcp.permissions AS permissions
                 FROM grouppermissions gp
                 JOIN permissioncollections_permissions pcp ON pcp.permissioncollections_id = gp.grouppermissions_id
                 WHERE gp.grouppermissions_key = ANY($1)",
                &[&member_of],
            )
            .await?;
        for r in &rows {
            let eid: i32 = r.get("entity_id");
            let p: Option<String> = r.get("permissions");
            if let Some(p) = p {
                if let Some(perm) = Permission::from_string(&p) {
                    perms.group_perms.entry(eid).or_default().push(perm);
                }
            }
        }
    }
    Ok(perms)
}
