pub async fn insert_layer(c: &tokio_postgres::Client, l: &Layer, conflicts: &Conflicts) -> WResult<()> {
    let id = l.id.ok_or(WriteError::Runtime)?;
    let now = db::now();
    if let Some(a) = &l.appearance {
        if a.id.is_none() {
            return Err(WriteError::Runtime);
        }
        if a.fresh {
            // POST session is empty: no NonUniqueObject possible
            wipe_appearance(c, a).await?;
        }
        let _ = conflicts;
    }
    exec(
        c,
        "INSERT INTO layers (id, created, modified, description, name, appearance_id, source_id)
         VALUES ($1,$2,$3,$4,$5,$6,$7)",
        &[
            &id,
            &now,
            &now,
            &l.description,
            &l.name,
            &l.appearance.as_ref().and_then(|a| a.id),
            &None::<i32>,
        ],
    )
    .await?;
    Ok(())
}

pub async fn update_layer(c: &tokio_postgres::Client, l: &Layer, m: &Mutation, conflicts: &Conflicts) -> WResult<()> {
    let id = l.id.ok_or(WriteError::Runtime)?;
    let now = db::now();
    let appearance_id = if m.refs.contains("appearance") {
        match &l.appearance {
            None => None,
            Some(a) => {
                let aid = a.id.ok_or(WriteError::Runtime)?; // transient appearance has an id assigned
                if conflicts.appearance.contains(&aid) {
                    return Err(WriteError::Runtime); // NonUniqueObjectException
                }
                if a.fresh && !was_just_inserted(a, conflicts) {
                    wipe_appearance(c, a).await?;
                }
                Some(aid)
            }
        }
    } else {
        l.appearance.as_ref().and_then(|a| a.id)
    };
    exec(
        c,
        "UPDATE layers SET description=$2, name=$3, appearance_id=$4, source_id=$5, modified=$6 WHERE id=$1",
        &[
            &id,
            &l.description,
            &l.name,
            &appearance_id,
            &l.source.as_ref().and_then(|s| s.id),
            &now,
        ],
    )
    .await?;
    Ok(())
}

/// An appearance that has no DB row yet was inserted during id assignment
/// phase by the caller; we detect it via the `inserted` marker list.
fn was_just_inserted(a: &LayerAppearance, conflicts: &Conflicts) -> bool {
    let _ = a;
    let _ = conflicts;
    false
}

pub async fn insert_appearance_root(c: &tokio_postgres::Client, a: &LayerAppearance) -> WResult<()> {
