{"content": "//! Write path: inserts, updates (incl. the detached "wipe-update" semantics of
//! cascaded associations) and deletes, mirroring Hibernate flush behaviour.

use std::collections::{HashMap, HashSet};

use deadpool_postgres::Pool;
use tokio_postgres::types::ToSql;

use crate::db;
use crate::javadoc;
use crate::model::*;

/// Errors of the write phase. `Runtime` mirrors a Java RuntimeException
/// (NonUniqueObjectException, TransientObjectException, StStateException,
/// constraint violations, NPEs): the transaction is rolled back and the
/// controller reports 400 (POST) / 404 (PUT/DELETE).
#[derive(Debug)]
pub enum WriteError {
    Runtime,
    Infra(String),
}

pub type WResult<T> = Result<T, WriteError>;

fn dberr<E: std::fmt::Display>(e: E) -> WriteError {
    WriteError::Runtime
        .into_infra_if_needed(&e.to_string())
}

trait IntoInfra {
    fn into_infra_if_needed(self, msg: &str) -> WriteError;
}

impl IntoInfra for WriteError {
    fn into_infra_if_needed(self, _msg: &str) -> WriteError {
        WriteError::Runtime
    }
}

/// Tracks which refs/collections were replaced by a PUT body.
#[derive(Default, Clone, Debug)]
pub struct Mutation {
    pub refs: HashSet<String>,
    pub collections: HashSet<String>,
}

impl Mutation {
    pub fn touches(&self, name: &str) -> bool {
        self.refs.contains(name) || self.collections.contains(name)
    }
}

/// Loaded entity ids that are attached to the "session" and would trigger
/// Hibernate's NonUniqueObjectException when a detached instance with the
/// same id is re-attached through a cascading association.
#[derive(Default, Clone)]
pub struct Conflicts {
    pub appearance: Vec<i32>,
    pub tilegrid: Vec<i32>,
    pub extent: Vec<i32>,
}

async fn exec(c: &tokio_postgres::Client, sql: &str, params: &[&(dyn ToSql + Sync)]) -> WResult<u64> {
    c.execute(sql, params).await.map_err(|e| {
        let _ = &dberr(e);
        WriteError::Runtime
    })
}

/// UPDATE that must affect exactly one row (mirrors Hibernate's
/// StaleStateException on re-attaching a detached entity that does not exist).
async fn exec_one(c: &tokio_postgres::Client, sql: &str, params: &[&(dyn ToSql + Sync)]) -> WResult<()> {
    let n = exec(c, sql, params).await?;
    if n != 1 {
        return Err(WriteError::Runtime);
    }
    Ok(())
}

// ---------------------------------------------------------------------------
// id allocation (autocommit; consumed even if the transaction rolls back)
// ---------------------------------------------------------------------------

pub async fn assign_ids_create(pool: &Pool, layer: &mut Layer) -> WResult<()> {
    layer.id = Some(db::next_id(pool).await.map_err(WriteError::Infra)?);
    if let Some(a) = layer.appearance.as_mut() {
        if a.id.is_none() {
            a.id = Some(db::next_id(pool).await.map_err(WriteError::Infra)?);
            assign_appearance_children_ids(pool, a).await?;
        }
    }
    Ok(())
}

async fn assign_appearance_children_ids(_pool: &Pool, _a: &mut LayerAppearance) -> WResult<()> {
    Ok(())
}

pub async fn assign_ids_root(pool: &Pool) -> WResult<i32> {
    db::next_id(pool).await.map_err(WriteError::Infra)
}

pub async fn assign_grid_ids(pool: &Pool, g: &mut TileGrid) -> WResult<()> {
    if g.id.is_none() {
        g.id = Some(db::next_id(pool).await.map_err(WriteError::Infra)?);
    }
    if let Some(e) = g.extent.as_mut() {
        if e.id.is_none() {
            e.id = Some(db::next_id(pool).await.map_err(WriteError::Infra)?);
        }
    }
    Ok(())
}

// ---------------------------------------------------------------------------
// INSERT helpers
// ---------------------------------------------------------------------------

async fn insert_extent(c: &tokio_postgres::Client, e: &Extent) -> WResult<()> {
    let id = e.id.ok_or(WriteError::Runtime)?;
    let now = db::now();
    let (llx, lly) = match e.lower_left {
        Some(p) => (Some(p.x), Some(p.y)),
        None => (None, None),
    };
    let (urx, ury) = match e.upper_right {
        Some(p) => (Some(p.x), Some(p.y)),
        None => (None, None),
    };
    exec(
        c,
        "INSERT INTO extents (id, created, modified, lowerleft_x, lowerleft_y, upperright_x, upperright_y)
         VALUES ($1,$2,$3,$4,$5,$6,$7)",
        &[&id, &now, &now, &llx, &lly, &urx, &ury],
    )
    .await?;
    Ok(())
}

async fn write_tilegrid_collections(c: &tokio_postgres::Client, g: &TileGrid) -> WResult<()> {
    let id = g.id.ok_or(WriteError::Runtime)?;
    exec(c, "DELETE FROM tilegrid_resolution WHERE tilegrid_id = $1", &[&id]).await?;
    if let Some(res) = &g.resolutions {
        for (idx, r) in res.iter().enumerate() {
            exec(
                c,
                "INSERT INTO tilegrid_resolution (tilegrid_id, resolution, idx) VALUES ($1,$2,$3)",
                &[&id, r, &(idx as i32)],
            )
            .await?;
        }
    }
    if g.is_wmts {
        exec(c, "DELETE FROM wmtstilegrids_matrixids WHERE wmtstilegrids_id = $1", &[&id]).await?;
        if let Some(mids) = &g.matrix_ids {
            for m in mids {
                exec(
                    c,
                    "INSERT INTO wmtstilegrids_matrixids (wmtstilegrids_id, matrixids) VALUES ($1,$2)",
                    &[&id, m],
                )
                .await?;
            }
        }
    }
    Ok(())
}

async fn insert_tilegrid(c: &tokio_postgres::Client, g: &TileGrid) -> WResult<()> {
    let id = g.id.ok_or(WriteError::Runtime)?;
    let now = db::now();
    if let Some(e) = &g.extent {
        if e.fresh && e.id.is_some() {
            insert_extent(c, e).await?;
        }
    }
    let extent_id = g.extent.as_ref().and_then(|e| e.id);
    let (ox, oy) = match g.origin {
        Some(p) => (Some(p.x), Some(p.y)),
        None => (None, None),
    };
    exec(
        c,
        "INSERT INTO tilegrids (id, created, modified, tilegridorigin_x, tilegridorigin_y, tilesize, type, tilegridextent_id)
         VALUES ($1,$2,$3,$4,$5,$6,$7,$8)",
        &[&id, &now, &now, &ox, &oy, &g.tile_size, &g.grid_type, &extent_id],
    )
    .await?;
    if g.is_wmts {
        exec(c, "INSERT INTO wmtstilegrids (id) VALUES ($1)", &[&id]).await?;
    }
    write_tilegrid_collections(c, g).await?;
    Ok(())
}

async fn wipe_extent(c: &tokio_postgres::Client, e: &Extent) -> WResult<()> {
    let id = e.id.ok_or(WriteError::Runtime)?;
    let now = db::now();
    let (llx, lly) = match e.lower_left {
        Some(p) => (Some(p.x), Some(p.y)),
        None => (None, None),
    };
    let (urx, ury) = match e.upper_right {
        Some(p) => (Some(p.x), Some(p.y)),
        None => (None, None),
    };
    exec_one(
        c,
        "UPDATE extents SET lowerleft_x=$2, lowerleft_y=$3, upperright_x=$4, upperright_y=$5, modified=$6 WHERE id=$1",
        &[&id, &llx, &lly, &urx, &ury, &now],
    )
    .await
}

async fn wipe_tilegrid(c: &tokio_postgres::Client, g: &TileGrid, conflicts: &Conflicts) -> WResult<()> {
    let id = g.id.ok_or(WriteError::Runtime)?;
    let now = db::now();
    // nested extent of a detached grid
    let extent_id = match &g.extent {
        None => None,
        Some(e) => {
            if e.id.is_none() {
                insert_extent(c, e).await?;
            } else {
                let eid = e.id.unwrap();
                if conflicts.extent.contains(&eid) {
                    return Err(WriteError::Runtime); // NonUniqueObjectException
                }
                if e.fresh {
                    wipe_extent(c, e).await?;
                }
            }
            e.id
        }
    };
    let (ox, oy) = match g.origin {
        Some(p) => (Some(p.x), Some(p.y)),
        None => (None, None),
    };
    exec_one(
        c,
        "UPDATE tilegrids SET type=$2, tilegridorigin_x=$3, tilegridorigin_y=$4, tilesize=$5, tilegridextent_id=$6, modified=$7 WHERE id=$1",
        &[&id, &g.grid_type, &ox, &oy, &g.tile_size, &extent_id, &now],
    )
    .await?;
    write_tilegrid_collections(c, g).await?;
    Ok(())
}

fn prop_rows(a: &LayerAppearance) -> WResult<Vec<(String, Option<String>)>> {
    let mut out = Vec::new();
    match &a.properties {
        PropState::Loaded(props) => {
            for (k, v) in props {
                let s = match v {
                    PropValue::Str(s) => s.clone(),
                    PropValue::Long(l) => l.to_string(),
                    PropValue::Double(d) => javadoc::java_double_to_string(*d),
                    PropValue::Bool(b) => b.to_string(),
                };
                out.push((k.clone(), Some(s)));
            }
        }
        PropState::Raw(raw) => {
            for (k, v) in raw {
                if v.is_null() {
                    // PropertyValueConverter.convertToDatabaseColumn NPEs
                    return Err(WriteError::Runtime);
                }
                out.push((k.clone(), Some(javadoc::java_value_to_string(v))));
            }
        }
        PropState::Null => {}
    }
    Ok(out)
}

async fn write_appearance_properties(c: &tokio_postgres::Client, a: &LayerAppearance) -> WResult<()> {
    let id = a.id.ok_or(WriteError::Runtime)?;
    let rows = prop_rows(a)?;
    exec(c, "DELETE FROM layerappearances_properties WHERE appearance_id = $1", &[&id]).await?;
    for (k, v) in &rows {
        exec(
            c,
            "INSERT INTO layerappearances_properties (appearance_id, property, value) VALUES ($1,$2,$3)",
            &[&id, k, v],
