    let now = db::now();
    exec(
        c,
        "INSERT INTO persons (id, created, modified, birthday, email, firstname, language, lastname)
         VALUES ($1,$2,$3,$4,$5,$6,$7,$8)",
        &[&id, &now, &now, &u.birthday, &u.email, &u.first_name, &u.language, &u.last_name],
    )
    .await?;
    exec(
        c,
        "INSERT INTO users (accountname, active, password, id) VALUES ($1,$2,$3,$4)",
        &[&u.account_name, &u.active, &u.password, &id],
    )
    .await?;
    write_user_roles(c, u).await?;
    write_user_groups(c, u).await?;
    Ok(())
}

