pub async fn insert_group(c: &tokio_postgres::Client, g: &UserGroup) -> WResult<()> {
    let id = g.id.ok_or(WriteError::Runtime)?;
    let now = db::now();
    if let Some(o) = &g.owner {
        if o.id.is_none() {
            return Err(WriteError::Runtime);
        }
    }
    exec(
        c,
        "INSERT INTO usergroups (id, created, modified, name, owner_id) VALUES ($1,$2,$3,$4,$5)",
        &[&id, &now, &now, &g.name, &g.owner.as_ref().and_then(|o| o.id)],
    )
    .await?;
    write_group_members(c, g).await?;
    write_group_roles(c, g).await?;
    Ok(())
}

pub async fn update_group(c: &tokio_postgres::Client, g: &UserGroup, m: &Mutation) -> WResult<()> {
    let id = g.id.ok_or(WriteError::Runtime)?;
    let now = db::now();
    let owner_id = if m.refs.contains("owner") {
        match &g.owner {
            None => None,
            Some(o) => {
                if o.id.is_none() {
                    return Err(WriteError::Runtime); // transient
                }
                o.id
            }
        }
    } else {
        g.owner.as_ref().and_then(|o| o.id)
    };
    exec(
        c,
        "UPDATE usergroups SET name=$2, owner_id=$3, modified=$4 WHERE id=$1",
        &[&id, &g.name, &owner_id, &now],
    )
    .await?;
    if m.collections.contains("members") {
        write_group_members(c, g).await?;
    }
    if m.collections.contains("roles") {
        write_group_roles(c, g).await?;
    }
    Ok(())
}

