pub async fn update_layer(
    c: &tokio_postgres::Client,
    l: &Layer,
    m: &Mutation,
    conflicts: &Conflicts,
) -> WResult<()> {
    let id = l.id.ok_or(WriteError::Runtime)?;
    let now = db::now();
    let appearance_id = if m.refs.contains("appearance") {
        write_appearance_ref(c, &l.appearance, conflicts).await?
    } else {
        l.appearance.as_ref().and_then(|a| a.id)
    };
    // source can only be nulled out (any non-null value fails deserialization)
    let source_id = if m.refs.contains("source") {
        None
    } else {
        l.source.as_ref().and_then(|s| s.id)
    };
    exec(
        c,
        "UPDATE layers SET description=$2, name=$3, appearance_id=$4, source_id=$5, modified=$6 WHERE id=$1",
        &[&id, &l.description, &l.name, &appearance_id, &source_id, &now],
    )
    .await?;
    Ok(())
