async fn write_xyz_resolutions(c: &tokio_postgres::Client, d: &DataSource) -> WResult<()> {
    let id = d.id.ok_or(WriteError::Runtime)?;
    exec(c, "DELETE FROM xyzlayerdatasrc_resolution WHERE xyzlayerdatasrc_id = $1", &[&id]).await?;
    if let Some(res) = &d.resolutions {
        for (idx, p) in res.iter().enumerate() {
            let blob: Option<Vec<u8>> = p.map(|pt| javadoc::serialize_point2d_double(pt.x, pt.y));
            exec(
                c,
                "INSERT INTO xyzlayerdatasrc_resolution (xyzlayerdatasrc_id, resolution, idx) VALUES ($1,$2,$3)",
                &[&id, &blob, &(idx as i32)],
            )
            .await?;
        }
    }
    Ok(())
}

async fn write_wmts_urls(c: &tokio_postgres::Client, d: &DataSource) -> WResult<()> {
