    Appearances,
}

/// Tracks which refs/collections were replaced by a PUT body (needed because
/// Hibernate only rewrites collections that were actually touched).
#[derive(Default, Clone, Debug)]
pub struct Mutation {
    pub refs: std::collections::HashSet<String>,
    pub collections: std::collections::HashSet<String>,
}

impl Mutation {
    pub fn set_ref(&mut self, name: &str) {
        self.refs.insert(name.to_string());
    }
    pub fn set_collection(&mut self, name: &str) {
        self.collections.insert(name.to_string());
    }
}

