//! Rust port of a slice of the SHOGun-Core REST API (users, groups, roles,
//! layers, layerdatasources, layerappearances) with the same behaviour as the
//! original Spring/Hibernate/Jackson application.

mod auth;
mod db;
mod handlers;
mod jackson;
mod javadoc;
mod model;
mod perms;
mod persist;

use axum::routing::any;
use axum::Router;
use handlers::AppState;

#[tokio::main]
async fn main() {
    let database_url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
        eprintln!("DATABASE_URL is not set");
        std::process::exit(1);
    });
    let port: u16 = std::env::var("PORT")
        .ok()
        .and_then(|s| s.parse().ok())
        .unwrap_or(8080);

    let pool = db::create_pool(&database_url).unwrap_or_else(|e| {
        eprintln!("could not create database pool: {}", e);
        std::process::exit(1);
    });

    // Best-effort readiness probe: the server must answer within 60s, the pool
    // connects lazily anyway.
    {
        let pool = pool.clone();
        tokio::spawn(async move {
            for _ in 0..30 {
                if let Ok(c) = pool.get().await {
                    if c.execute("SELECT 1", &[]).await.is_ok() {
                        return;
                    }
                }
                tokio::time::sleep(std::time::Duration::from_millis(500)).await;
            }
        });
    }

    let state = AppState { pool };
    let app = Router::new()
        .route("/rest", any(handlers::rest_handler))
        .route("/rest/{*path}", any(handlers::rest_handler))
        .fallback(any(handlers::other_handler))
        .with_state(state);

    let addr = format!("0.0.0.0:{}", port);
    let listener = tokio::net::TcpListener::bind(&addr).await.unwrap_or_else(|e| {
        eprintln!("could not bind to {}: {}", addr, e);
        std::process::exit(1);
    });
    eprintln!("listening on {}", addr);
    axum::serve(listener, app).await.unwrap_or_else(|e| {
        eprintln!("server error: {}", e);
        std::process::exit(1);
    });
}

