pub fn create_pool(database_url: &str) -> Result<Pool, String> {
    let pg_cfg: tokio_postgres::Config = database_url
        .parse()
        .map_err(|e: tokio_postgres::Error| format!("invalid DATABASE_URL: {}", e))?;
    let manager = deadpool_postgres::Manager::new(pg_cfg, NoTls);
    let pool = Pool::builder(manager)
        .max_size(10)
        .build()
        .map_err(|e| format!("pool build error: {}", e))?;
    Ok(pool)
}

input.oldString:
pub fn create_pool(database_url: &str) -> Result<Pool, String> {
    let pg_cfg: tokio_postgres::Config = database_url
        .parse()
        .map_err(|e: tokio_postgres::Error| format!("invalid DATABASE_URL: {}", e))?;
    let mut cfg = deadpool_postgres::Config::default();
    cfg.host = pg_cfg.get_hosts().first().and_then(|h| match h {
        tokio_postgres::config::Host::Tcp(s) => Some(s.clone()),
        _ => None,
    });
    cfg.port = pg_cfg.get_ports().first().copied();
    cfg.user = pg_cfg.get_user().map(|s| s.to_string());
    cfg.password = pg_cfg.get_password().map(|s| String::from_utf8_lossy(s).to_string());
    cfg.dbname = pg_cfg.get_dbname().map(|s| s.to_string());
    let manager = cfg.create_manager(Some(Runtime::Tokio1));
    Pool::builder(manager)
        .max_size(10)
        .build()
        .map_err(|e| format!("pool build error: {}", e))
}

